const BANK_VERSION="2026.10.17.2";
const BANK=[{"id": "c001", "topic": "向量空間與子空間", "en": "Every vector space contains the zero vector.", "zh": "每個向量空間都包含零向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "零向量是向量加法的單位元素，是向量空間定義的一部分。空集合不是向量空間。", "kind": "原創觀念", "level": 1}, {"id": "c002", "topic": "向量空間與子空間", "en": "A subset containing the zero vector is necessarily a subspace.", "zh": "一個集合只要包含零向量，就一定是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "還必須對加法與純量乘法封閉。例如 {(0,0),(1,0)} 含零向量，但 2(1,0) 不在集合內。", "kind": "原創觀念", "level": 1}, {"id": "c003", "topic": "向量空間與子空間", "en": "The solution set of Ax = 0 is a subspace.", "zh": "齊次方程 Ax = 0 的解集合是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 Ax=0、Ay=0，則 A(cx+dy)=cAx+dAy=0；因此任意線性組合仍在解集合內。", "kind": "原創觀念", "level": 1}, {"id": "c004", "topic": "向量空間與子空間", "en": "If b is nonzero, the solution set of Ax = b is a subspace.", "zh": "若 b 不為零，Ax = b 的解集合是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "零向量不會滿足 A0=b，因此解集合不含零向量；即使有解也不是子空間。", "kind": "原創觀念", "level": 1}, {"id": "c005", "topic": "向量空間與子空間", "en": "The intersection of two subspaces is a subspace.", "zh": "兩個子空間的交集仍是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "交集中的向量同時屬於兩個空間；線性組合在兩邊都封閉，因此也在交集中。", "kind": "原創觀念", "level": 1}, {"id": "c006", "topic": "向量空間與子空間", "en": "The union of any two subspaces is a subspace.", "zh": "任意兩個子空間的聯集都是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "在 R² 中，x 軸和 y 軸的聯集不含 (1,1)，但 (1,0)+(0,1)=(1,1)，所以不對加法封閉。", "kind": "原創觀念", "level": 1}, {"id": "c007", "topic": "向量空間與子空間", "en": "If U and W are subspaces of the same vector space and U is contained in W, then U union W is a subspace.", "zh": "若 U、W 都是子空間且 U 包含於 W，則 U 與 W 的聯集是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "此時聯集就是 W。聯集通常不是子空間，但一方包含另一方時可以。", "kind": "原創觀念", "level": 1}, {"id": "c008", "topic": "向量空間與子空間", "en": "The set of all vectors of length one in R² is a subspace.", "zh": "R² 中所有長度為 1 的向量形成子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "此集合不含零向量，而且向量乘以 2 後長度變成 2，不再屬於原集合。", "kind": "原創觀念", "level": 1}, {"id": "c009", "topic": "向量空間與子空間", "en": "The set of all symmetric real n by n matrices is a subspace.", "zh": "所有 n 階實對稱矩陣形成子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 Aᵀ=A、Bᵀ=B，則 (aA+bB)ᵀ=aA+bB，而且零矩陣對稱。", "kind": "原創觀念", "level": 1}, {"id": "c010", "topic": "向量空間與子空間", "en": "The set of all invertible n by n real matrices is a subspace.", "zh": "所有 n 階可逆實矩陣形成子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "零矩陣不可逆，因此集合不含零向量。I 與 −I 都可逆，但相加是不可逆的零矩陣。", "kind": "原創觀念", "level": 1}, {"id": "c011", "topic": "向量空間與子空間", "en": "The set of polynomials of degree exactly two is a vector space.", "zh": "次數恰為 2 的所有多項式形成向量空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "零多項式不在集合內；x² 與 −x² 的和也不再是二次多項式。", "kind": "原創觀念", "level": 1}, {"id": "c012", "topic": "向量空間與子空間", "en": "The set P₂ of polynomials of degree at most two has dimension three.", "zh": "次數至多 2 的多項式空間 P₂，其維度為 3。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "基底可選 {1,x,x²}，所以有三個獨立的係數，也就是三個自由度。P₂ 包含零多項式。", "kind": "原創觀念", "level": 1}, {"id": "c013", "topic": "向量空間與子空間", "en": "A subspace of a finite-dimensional vector space can have a larger dimension than the original space.", "zh": "有限維向量空間的子空間，其維度可以大於原空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "子空間中的線性獨立組也在原空間中，因此 dim U ≤ dim V。", "kind": "原創觀念", "level": 1}, {"id": "c014", "topic": "向量空間與子空間", "en": "A subspace U of a finite-dimensional space V must equal V if dim U = dim V.", "zh": "若 U 是有限維空間 V 的子空間且維度相同，則 U=V。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "U 的基底已有 dim V 個線性獨立向量，因而也是 V 的基底。此題必須有 U 包含於 V 的前提。", "kind": "原創觀念", "level": 1}, {"id": "c015", "topic": "向量空間與子空間", "en": "Two subspaces having the same dimension must be equal.", "zh": "兩個子空間的維度相同，就一定是同一個子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "R² 中 x 軸與 y 軸的維度都是 1，但兩者不是同一條直線。必須再有包含關係才能由同維推出相等。", "kind": "原創觀念", "level": 1}, {"id": "c016", "topic": "向量空間與子空間", "en": "For subspaces U and W of the same vector space, U + W consists of all vectors u + w with u in U and w in W.", "zh": "U+W 是所有 u+w 的集合，其中 u 屬於 U、w 屬於 W。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "空間的和是讓兩邊的向量自由選取後相加，不只是把兩個集合聯集。U+W 也是子空間。", "kind": "原創觀念", "level": 1}, {"id": "c017", "topic": "向量空間與子空間", "en": "For finite-dimensional subspaces U and W of the same vector space, dim(U + W) always equals dim U + dim W.", "zh": "同一向量空間的有限維子空間 U、W，是否總有 dim(U+W)=dim U+dim W？", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "正確公式為 dim(U+W)=dim U+dim W−dim(U∩W)。交集中的自由度不能重複計算。", "kind": "原創觀念", "level": 1}, {"id": "c018", "topic": "向量空間與子空間", "en": "If U and W are subspaces of the same vector space and U intersection W = {0}, then every vector in U + W has a unique decomposition u + w.", "zh": "若 U∩W={0}，則 U+W 中每個向量都只有一種 u+w 分解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 u₁+w₁=u₂+w₂，則 u₁−u₂=w₂−w₁ 屬於交集，只能為 0，因此兩邊分別相等。", "kind": "原創觀念", "level": 2}, {"id": "c019", "topic": "向量空間與子空間", "en": "The empty set is a subspace.", "zh": "空集合是子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "空集合不含零向量。只有零向量的集合 {0} 才是維度為 0 的子空間。", "kind": "原創觀念", "level": 1}, {"id": "c020", "topic": "向量空間與子空間", "en": "The vector space of all real polynomials is finite-dimensional.", "zh": "所有實係數多項式構成有限維向量空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "1,x,x²,… 可以一直增加線性獨立向量，沒有有限個多項式能張成所有次數的多項式。", "kind": "原創觀念", "level": 1}, {"id": "c021", "topic": "Span、線性獨立與基底", "en": "span{v} is the set of all scalar multiples of v.", "zh": "span{v} 是 v 的所有純量倍數的集合。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "span{v}={cv：c 為純量}。v 非零時是一條通過原點的直線；v=0 時只有零向量。", "kind": "原創觀念", "level": 1}, {"id": "c022", "topic": "Span、線性獨立與基底", "en": "span{u,v} contains only u+v.", "zh": "span{u,v} 只包含 u+v 這個向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "span{u,v} 包含所有 au+bv，a、b 可以分別自由變動。u+v 只是 a=b=1 的一個例子。", "kind": "原創觀念", "level": 1}, {"id": "c023", "topic": "Span、線性獨立與基底", "en": "span{u+v} always equals span{u,v}.", "zh": "span{u+v} 永遠等於 span{u,v}。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "令 u=(1,0)、v=(0,1)，前者只有 (c,c) 這條直線，後者是整個 R²。把向量先相加會綁住係數。", "kind": "原創觀念", "level": 1}, {"id": "c024", "topic": "Span、線性獨立與基底", "en": "Adding a vector already in the span does not change the span.", "zh": "加入一個原本就在張成空間內的向量，不會改變張成空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 w=a₁v₁+…+aₖvₖ，任何含 w 的線性組合都能改寫成原向量的組合，因此沒有新增方向。", "kind": "原創觀念", "level": 1}, {"id": "c025", "topic": "Span、線性獨立與基底", "en": "Any set containing the zero vector is linearly dependent.", "zh": "只要一組向量包含零向量，這組向量就線性相依。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "把零向量的係數設為 1、其他係數設為 0，就得到非全零係數的零線性組合。", "kind": "原創觀念", "level": 1}, {"id": "c026", "topic": "Span、線性獨立與基底", "en": "Two nonzero vectors are linearly dependent exactly when one is a scalar multiple of the other.", "zh": "兩個非零向量線性相依，若且唯若其中一個是另一個的純量倍數。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "兩向量相依代表 au+bv=0 有非平凡解，由於向量非零，可整理成 u=cv。", "kind": "原創觀念", "level": 1}, {"id": "c027", "topic": "Span、線性獨立與基底", "en": "Three nonzero vectors must be linearly independent if no two are scalar multiples.", "zh": "三個非零向量若任兩個都不是倍數，就一定線性獨立。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "(1,0)、(0,1)、(1,1) 任兩個都不是倍數，但第三個等於前兩個相加。兩兩獨立不等於整組獨立。", "kind": "原創觀念", "level": 1}, {"id": "c028", "topic": "Span、線性獨立與基底", "en": "Every subset of a linearly independent set is linearly independent.", "zh": "線性獨立組的任意子集仍然線性獨立。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若子集已有非平凡零線性組合，把被刪向量的係數補成 0，原組也會相依，產生矛盾。", "kind": "原創觀念", "level": 1}, {"id": "c029", "topic": "Span、線性獨立與基底", "en": "Every subset of a linearly dependent set is linearly dependent.", "zh": "線性相依組的每個子集都線性相依。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "{(1,0),(0,1),(1,1)} 相依，但取前兩個就線性獨立。移除多餘向量可能消除相依性。", "kind": "原創觀念", "level": 1}, {"id": "c030", "topic": "Span、線性獨立與基底", "en": "A superset of a linearly dependent set is linearly dependent.", "zh": "包含一組線性相依向量的更大集合，也線性相依。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "原有非平凡零線性組合仍然成立，只需把新向量的係數設為 0。", "kind": "原創觀念", "level": 1}, {"id": "c031", "topic": "Span、線性獨立與基底", "en": "Any n+1 vectors in an n-dimensional space are linearly dependent.", "zh": "n 維空間中的任意 n+1 個向量都線性相依。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "n 維空間最多容納 n 個線性獨立向量。超過維度，就一定有多餘方向。", "kind": "原創觀念", "level": 1}, {"id": "c032", "topic": "Span、線性獨立與基底", "en": "Any n vectors in an n-dimensional space form a basis.", "zh": "n 維空間中的任意 n 個向量都是基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "數量正確仍不夠，還要線性獨立或能張成。例如 R² 的 (1,0)、(2,0) 不是基底。", "kind": "原創觀念", "level": 1}, {"id": "c033", "topic": "Span、線性獨立與基底", "en": "Any n linearly independent vectors in an n-dimensional space form a basis.", "zh": "n 維空間中任意 n 個線性獨立向量都是基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "個數已達空間維度，獨立組不可能再增加，因此必然張成整個空間。", "kind": "原創觀念", "level": 1}, {"id": "c034", "topic": "Span、線性獨立與基底", "en": "Any n vectors spanning an n-dimensional space form a basis.", "zh": "若 n 個向量張成 n 維空間，這 n 個向量就是基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若相依，刪掉一個多餘向量後仍可張成，變成不到 n 個向量張成 n 維空間，矛盾。", "kind": "原創觀念", "level": 1}, {"id": "c035", "topic": "Span、線性獨立與基底", "en": "A basis is a linearly independent spanning set.", "zh": "基底就是既線性獨立、又能張成整個空間的一組向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "兩個條件缺一不可：獨立排除冗餘，張成保證不漏掉空間內任何向量。", "kind": "原創觀念", "level": 1}, {"id": "c036", "topic": "Span、線性獨立與基底", "en": "A finite-dimensional vector space has only one basis.", "zh": "有限維向量空間只有一組基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "R² 的 {(1,0),(0,1)} 與 {(1,1),(1,−1)} 都是基底。基底不唯一，但基底的個數固定。", "kind": "原創觀念", "level": 1}, {"id": "c037", "topic": "Span、線性獨立與基底", "en": "All bases of a finite-dimensional vector space have the same number of vectors.", "zh": "有限維向量空間的所有基底都有相同數量的向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "這個固定數量就是維度 dimension。維度是一個數字，基底則是一組向量。", "kind": "原創觀念", "level": 1}, {"id": "c038", "topic": "Span、線性獨立與基底", "en": "Every vector has a unique representation as a linear combination of a given basis.", "zh": "固定一組基底後，每個向量都有唯一的基底線性組合表示。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "存在性來自張成，唯一性來自線性獨立。兩個表示相減後，只能得到全零係數。", "kind": "原創觀念", "level": 1}, {"id": "c039", "topic": "Span、線性獨立與基底", "en": "Every linearly independent set in a finite-dimensional vector space can be extended to a basis.", "zh": "有限維空間內的線性獨立組，可以增加向量擴充成基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若尚未張成，就從原張成空間外取向量加入；這樣仍獨立，直到向量數達到維度。", "kind": "原創觀念", "level": 1}, {"id": "c040", "topic": "Span、線性獨立與基底", "en": "Every finite spanning set contains a basis.", "zh": "任何有限張成組都包含一組基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "不斷刪掉能由其他向量表示的多餘向量，直到剩下線性獨立的張成組即可。", "kind": "原創觀念", "level": 1}, {"id": "c041", "topic": "Rank 與四個基本子空間", "en": "For an m by n matrix A, rank(A) is at most min(m,n).", "zh": "m×n 矩陣 A 的秩不超過 min(m,n)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "欄向量位於 Rᵐ，最多 m 個獨立方向；又總共只有 n 欄，所以也不超過 n。", "kind": "原創觀念", "level": 1}, {"id": "c042", "topic": "Rank 與四個基本子空間", "en": "The row rank and column rank of any matrix are equal.", "zh": "任何矩陣的橫列秩和直行秩相等。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "這是秩的基本定理。因此 rank(A) 不會因為從橫列或直行方向觀察而得到不同答案。", "kind": "原創觀念", "level": 1}, {"id": "c043", "topic": "Rank 與四個基本子空間", "en": "rank(A) = rank(A transpose).", "zh": "A 與轉置矩陣 Aᵀ 的秩相等。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "轉置互換橫列與直行，而 row rank 等於 column rank，所以秩不變。", "kind": "原創觀念", "level": 1}, {"id": "c044", "topic": "Rank 與四個基本子空間", "en": "The rank of A equals the number of nonzero rows of A.", "zh": "A 的秩等於 A 本身非零橫列的數目。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "必須先化成階梯形再數非零橫列。例如兩個相同的非零橫列，只提供一個獨立方向。", "kind": "原創觀念", "level": 1}, {"id": "c045", "topic": "Rank 與四個基本子空間", "en": "The rank of A equals the number of pivots in a row-echelon form of A.", "zh": "A 的秩等於其階梯形矩陣中樞紐的數目。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "每個 pivot 對應一個獨立方向，也對應階梯形中的一個非零橫列。", "kind": "原創觀念", "level": 1}, {"id": "c046", "topic": "Rank 與四個基本子空間", "en": "Elementary row operations preserve rank.", "zh": "基本橫列運算保持秩不變。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "基本橫列運算等同左乘可逆矩陣 E，不會改變向量間獨立關係所決定的秩。", "kind": "原創觀念", "level": 1}, {"id": "c047", "topic": "Rank 與四個基本子空間", "en": "Elementary row operations preserve the row space.", "zh": "基本橫列運算保持橫列空間不變。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "新橫列都是舊橫列的線性組合，而且運算可逆，因此兩組橫列互相張成。", "kind": "原創觀念", "level": 1}, {"id": "c048", "topic": "Rank 與四個基本子空間", "en": "Elementary row operations preserve the column space as a set.", "zh": "基本橫列運算保持直行空間這個集合不變。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "只保證維度相同，不保證集合相同。把 (1,0)ᵀ 的兩橫列交換，直行空間由 x 軸變成 y 軸。", "kind": "原創觀念", "level": 1}, {"id": "c049", "topic": "Rank 與四個基本子空間", "en": "Elementary row operations preserve the null space.", "zh": "基本橫列運算保持零空間不變。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 B=EA 且 E 可逆，則 Bx=0 等價於 Ax=0，所以未知向量 x 的解集合相同。", "kind": "原創觀念", "level": 1}, {"id": "c050", "topic": "Rank 與四個基本子空間", "en": "Pivot columns of the original matrix form a basis for its column space.", "zh": "原矩陣中對應樞紐位置的直行，可作為其直行空間的基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "先以階梯形找出 pivot 的欄編號，再回原矩陣取那些直行；不要直接拿階梯形的直行代替。", "kind": "原創觀念", "level": 1}, {"id": "c051", "topic": "Rank 與四個基本子空間", "en": "Nonzero rows of a row-echelon form of A form a basis for the row space of A.", "zh": "A 的階梯形中所有非零橫列，是 A 橫列空間的一組基底。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "橫列運算保持 row space；階梯形非零橫列的 leading entries 錯開，因此它們線性獨立。", "kind": "原創觀念", "level": 1}, {"id": "c052", "topic": "Rank 與四個基本子空間", "en": "If A is a real m by n matrix, then N(A) is a subspace of Rᵐ.", "zh": "若 A 是 m×n 矩陣，則 N(A) 是 Rᵐ 的子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "Ax 的 x 有 n 個分量，所以 N(A) 包含於 Rⁿ；輸出與 column space 才位於 Rᵐ。", "kind": "原創觀念", "level": 1}, {"id": "c053", "topic": "Rank 與四個基本子空間", "en": "If A is a real m by n matrix, then Col(A) is a subspace of Rᵐ.", "zh": "若 A 是 m×n 矩陣，則 Col(A) 是 Rᵐ 的子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "每一欄有 m 個分量；所有欄的線性組合 Ax 也都有 m 個分量。", "kind": "原創觀念", "level": 1}, {"id": "c054", "topic": "Rank 與四個基本子空間", "en": "For an m by n matrix A, nullity(A) = n - rank(A).", "zh": "m×n 矩陣 A 滿足 nullity(A)=n−rank(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "rank-nullity 定理使用的是輸入維度 n，也就是未知數個數，不是輸出維度 m。", "kind": "原創觀念", "level": 1}, {"id": "c055", "topic": "Rank 與四個基本子空間", "en": "For an m by n matrix A, dim N(A transpose) = m - rank(A).", "zh": "m×n 矩陣 A 滿足 dim N(Aᵀ)=m−rank(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "對 Aᵀ 用秩零度定理。Aᵀ 有 m 欄，且 rank(Aᵀ)=rank(A)。", "kind": "原創觀念", "level": 1}, {"id": "c056", "topic": "Rank 與四個基本子空間", "en": "The null space of A is the orthogonal complement of its row space over the real numbers.", "zh": "實矩陣 A 的零空間，是其橫列空間的正交補空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "Ax=0 表示 x 與 A 的每一橫列內積為零，因此也與整個 row space 正交。", "kind": "原創觀念", "level": 1}, {"id": "c057", "topic": "Rank 與四個基本子空間", "en": "N(A transpose) is the orthogonal complement of Col(A) for a real matrix A.", "zh": "對實矩陣 A，N(Aᵀ) 是 Col(A) 的正交補空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "Aᵀy=0 表示 y 與 A 的每個直行都正交。兩個空間都位於 Rᵐ。", "kind": "原創觀念", "level": 1}, {"id": "c058", "topic": "Rank 與四個基本子空間", "en": "For a real matrix A, rank(A transpose A) = rank(A).", "zh": "對實矩陣 A，rank(AᵀA)=rank(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "因 xᵀAᵀAx=||Ax||²，可證 N(AᵀA)=N(A)，再由相同輸入維度及秩零度定理得到同秩。", "kind": "原創觀念", "level": 2}, {"id": "c059", "topic": "Rank 與四個基本子空間", "en": "If AB is defined, rank(AB) cannot exceed either rank(A) or rank(B).", "zh": "若 AB 有定義，rank(AB) 不會超過 rank(A) 或 rank(B)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "乘積的輸出落在 R(A) 內；而 B 已壓縮掉的輸入方向，後面的 A 也無法恢復。", "kind": "原創觀念", "level": 1}, {"id": "c060", "topic": "Rank 與四個基本子空間", "en": "For matrices A and B of the same size, rank(A+B) always equals rank(A)+rank(B).", "zh": "同尺寸矩陣永遠滿足 rank(A+B)=rank(A)+rank(B)。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "取 B=−A 且 A 非零，A+B=0，左邊為 0。一般只有 rank(A+B)≤rank(A)+rank(B)。", "kind": "原創觀念", "level": 1}, {"id": "c061", "topic": "Rank 與四個基本子空間", "en": "Multiplying a matrix by an invertible matrix on either side preserves its rank.", "zh": "矩陣左右任一側乘上尺寸合適的可逆矩陣，都保持秩不變。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "可逆矩陣只做可還原的座標變換，不會損失獨立方向。因此 rank(PAQ)=rank(A)。", "kind": "原創觀念", "level": 1}, {"id": "c062", "topic": "Rank 與四個基本子空間", "en": "A matrix has rank zero if and only if it is the zero matrix.", "zh": "矩陣秩為 0，若且唯若它是零矩陣。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "只要有一個非零直行，就至少有一個線性獨立向量，秩至少 1。", "kind": "原創觀念", "level": 1}, {"id": "c063", "topic": "Rank 與四個基本子空間", "en": "A nonzero outer product uv transpose has rank one when u and v are nonzero.", "zh": "當 u、v 都非零時，外積 uvᵀ 的秩為 1。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "每個直行都是 u 的倍數，且至少有一欄非零，因此直行空間恰為 span{u}。", "kind": "原創觀念", "level": 2}, {"id": "c064", "topic": "Rank 與四個基本子空間", "en": "If A² = 0, then A must be zero.", "zh": "若 A²=0，則 A 必為零矩陣。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "反例 A=[[0,1],[0,0]]。A 非零，但連乘兩次後為零。不要把純量性質直接搬到矩陣。", "kind": "原創觀念", "level": 1}, {"id": "c065", "topic": "Rank 與四個基本子空間", "en": "If A² = 0 for an n by n matrix, then rank(A) is at most n/2.", "zh": "若 n 階矩陣 A²=0，則 rank(A)≤n/2。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "A(Ax)=0 表示 R(A) 包含於 N(A)，所以 rank(A)≤nullity(A)=n−rank(A)。", "kind": "原創觀念", "level": 2}, {"id": "c066", "topic": "線性方程與可逆性", "en": "Ax=b is consistent if and only if b belongs to Col(A).", "zh": "Ax=b 有解，若且唯若 b 屬於 A 的直行空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "Ax 是 A 的各個直行以 x 的分量為係數做線性組合。因此能得到 b，等同 b 在欄空間內。", "kind": "原創觀念", "level": 1}, {"id": "c067", "topic": "線性方程與可逆性", "en": "Ax=b is consistent if and only if rank(A)=rank([A|b]).", "zh": "Ax=b 有解，若且唯若 A 與增廣矩陣 [A|b] 同秩。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "[A|b] 是在 A 右邊加入 b 這一欄。b 能由原欄表示時不新增獨立方向，秩不變。", "kind": "原創觀念", "level": 1}, {"id": "c068", "topic": "線性方程與可逆性", "en": "If rank([A|b]) is greater than rank(A), then Ax=b has no solution.", "zh": "若增廣矩陣的秩大於係數矩陣的秩，Ax=b 無解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "新增的 b 不在原本的直行空間內。消去後也會出現 0=非零常數 的矛盾式。", "kind": "原創觀念", "level": 1}, {"id": "c069", "topic": "線性方程與可逆性", "en": "A homogeneous linear system is always consistent.", "zh": "齊次線性方程組一定有解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "Ax=0 永遠至少有 x=0 這個 trivial solution；有解不代表一定有非零解。", "kind": "原創觀念", "level": 1}, {"id": "c070", "topic": "線性方程與可逆性", "en": "An m by n homogeneous system has a nontrivial solution if rank(A)<n.", "zh": "m×n 齊次系統若 rank(A)<n，就有非零解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "nullity(A)=n−rank(A)>0，存在自由變數，因此零空間不只有零向量。", "kind": "原創觀念", "level": 1}, {"id": "c071", "topic": "線性方程與可逆性", "en": "A homogeneous system with more unknowns than equations has a nonzero solution.", "zh": "未知數比方程式多的齊次系統，一定有非零解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 n>m，則 rank(A)≤m<n，因此 nullity(A)>0。注意此保證是針對齊次系統。", "kind": "原創觀念", "level": 1}, {"id": "c072", "topic": "線性方程與可逆性", "en": "A nonhomogeneous system with more unknowns than equations must have a solution.", "zh": "未知數比方程式多的非齊次系統，一定有解。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "仍可能有矛盾，例如同時要求 x+y+z=0 與 x+y+z=1。未知數多只能保證有解時不唯一。", "kind": "原創觀念", "level": 1}, {"id": "c073", "topic": "線性方程與可逆性", "en": "If Ax=b has one solution xₚ, then every solution is xₚ+z with z in N(A).", "zh": "若 xₚ 是 Ax=b 的一個解，所有解都可寫為 xₚ+z，其中 z∈N(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "A(xₚ+z)=b；反過來任何解 x 都滿足 A(x−xₚ)=0。所以通解是特解加齊次解。", "kind": "原創觀念", "level": 1}, {"id": "c074", "topic": "線性方程與可逆性", "en": "The difference of two solutions of Ax=b belongs to N(A).", "zh": "Ax=b 的任意兩個解相減，必屬於 N(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 Ax₁=Ax₂=b，則 A(x₁−x₂)=b−b=0。", "kind": "原創觀念", "level": 1}, {"id": "c075", "topic": "線性方程與可逆性", "en": "The sum of two solutions of Ax=b is always another solution of Ax=b.", "zh": "Ax=b 的兩個解相加，永遠仍是原方程的解。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "A(x₁+x₂)=2b，通常不是 b；只有 b=0 的齊次情況才保證加法封閉。", "kind": "原創觀念", "level": 1}, {"id": "c076", "topic": "線性方程與可逆性", "en": "If Ax=b is consistent and N(A)={0}, then the solution is unique.", "zh": "若 Ax=b 有解，且 N(A)={0}，則解唯一。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "兩解相減必在 N(A)，因此差只能為 0。一定要保留「有解」前提。", "kind": "原創觀念", "level": 1}, {"id": "c077", "topic": "線性方程與可逆性", "en": "Full column rank guarantees that Ax=b has a solution for every b in the codomain.", "zh": "滿直行秩保證對輸出空間內每個 b，Ax=b 都有解。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "滿直行秩保證若有解則唯一。對每個 b 有解需要滿橫列秩，例如 3×2 矩陣不可能張成 R³。", "kind": "原創觀念", "level": 1}, {"id": "c078", "topic": "線性方程與可逆性", "en": "Full row rank guarantees that Ax=b is consistent for every b in Rᵐ.", "zh": "m×n 矩陣若滿橫列秩，則每個 b∈Rᵐ 都使 Ax=b 有解。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "rank(A)=m 表示 Col(A)=Rᵐ，因此每個輸出向量都可達。", "kind": "原創觀念", "level": 1}, {"id": "c079", "topic": "線性方程與可逆性", "en": "A linear system over the real numbers can have exactly two distinct solutions.", "zh": "實數上的線性方程組可以恰有兩個不同的解。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "若有兩解 x₁、x₂，則 x₁+t(x₂−x₁) 對所有實數 t 都是解，因此有無限多解。", "kind": "原創觀念", "level": 1}, {"id": "c080", "topic": "線性方程與可逆性", "en": "For an n by n matrix, det(A) not equal to zero is equivalent to N(A)={0}.", "zh": "n 階矩陣 det(A)≠0，等價於 N(A)={0}。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "兩者都等價於 A 可逆、rank(A)=n、直行獨立、每個 b 都有唯一解。", "kind": "原創觀念", "level": 1}, {"id": "c081", "topic": "線性方程與可逆性", "en": "If a 3 by 3 matrix has determinant zero, its rank must be two.", "zh": "3×3 矩陣若行列式為零，其秩一定是 2。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "det(A)=0 只表示 rank(A)<3，因此可能是 0、1 或 2。零矩陣的秩就是 0。", "kind": "原創觀念", "level": 1}, {"id": "c082", "topic": "線性方程與可逆性", "en": "If a square matrix has a left inverse, it is invertible.", "zh": "方陣若有左反矩陣，則它可逆。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 BA=I，則 Ax=0 推出 x=BAx=0，所以滿秩並可逆。方陣的單側逆可推出雙側逆。", "kind": "原創觀念", "level": 2}, {"id": "c083", "topic": "線性方程與可逆性", "en": "If A and B are square matrices of the same size and AB=0, then A=0 or B=0.", "zh": "同階方陣若 AB=0，則 A=0 或 B=0。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "A=diag(1,0)、B=diag(0,1) 都非零，但 AB=0。矩陣可能存在零因子。", "kind": "原創觀念", "level": 1}, {"id": "c084", "topic": "線性方程與可逆性", "en": "If A is invertible and AB=AC, then B=C.", "zh": "若 A 可逆且 AB=AC，則 B=C。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "等式兩邊左乘 A⁻¹ 即得 B=C。若 A 不可逆就不能隨意約掉。", "kind": "原創觀念", "level": 1}, {"id": "c085", "topic": "線性方程與可逆性", "en": "If Ax=b has a unique solution for one b, then N(A)={0}.", "zh": "若某一個 b 使 Ax=b 有唯一解，則 N(A)={0}。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若存在非零 z∈N(A)，唯一解 xₚ 加上 z 又是另一解，矛盾。但這不保證對每個 b 都有解。", "kind": "原創觀念", "level": 2}, {"id": "c086", "topic": "線性映射、Kernel 與 Range", "en": "A linear map T satisfies T(0)=0.", "zh": "線性映射 T 必滿足 T(0)=0。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "由 T(0+0)=T(0)+T(0)，兩邊扣掉 T(0)，得到 T(0)=0。", "kind": "原創觀念", "level": 1}, {"id": "c087", "topic": "線性映射、Kernel 與 Range", "en": "Any map satisfying T(0)=0 is linear.", "zh": "任何滿足 T(0)=0 的映射都是線性的。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "T(x)=x² 滿足 T(0)=0，但 T(1+1)=4，不等於 T(1)+T(1)=2。必要條件不等於充分條件。", "kind": "原創觀念", "level": 1}, {"id": "c088", "topic": "線性映射、Kernel 與 Range", "en": "A map is linear if it preserves both addition and scalar multiplication.", "zh": "映射若保持加法與純量乘法，就是線性映射。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "定義為 T(u+v)=T(u)+T(v)，以及 T(cu)=cT(u)；也可合寫 T(au+bv)=aT(u)+bT(v)。", "kind": "原創觀念", "level": 1}, {"id": "c089", "topic": "線性映射、Kernel 與 Range", "en": "T(x)=Ax+b is linear even when b is nonzero.", "zh": "即使 b≠0，T(x)=Ax+b 仍然是線性映射。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "T(0)=b≠0，違反線性必要條件。這種形式稱為仿射映射 affine map。", "kind": "原創觀念", "level": 1}, {"id": "c090", "topic": "線性映射、Kernel 與 Range", "en": "For a linear map T: V to W, ker(T) is a subspace of V.", "zh": "對線性映射 T:V→W，ker(T) 是輸入空間 V 的子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "kernel={v∈V：T(v)=0}，元素是被映成零的輸入，不是輸出的集合。", "kind": "原創觀念", "level": 1}, {"id": "c091", "topic": "線性映射、Kernel 與 Range", "en": "For a linear map T: V to W, R(T) is a subspace of W.", "zh": "對線性映射 T:V→W，R(T) 是陪域 W 的子空間。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "range={T(v)：v∈V}，包含實際可得到的輸出。它可能只是 W 的一部分。", "kind": "原創觀念", "level": 1}, {"id": "c092", "topic": "線性映射、Kernel 與 Range", "en": "The range and the codomain of a linear map are always equal.", "zh": "線性映射的值域和陪域永遠相等。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "T:R→R²，T(t)=(t,0)，陪域是 R²，值域卻只有 x 軸。相等時才稱為滿射 onto。", "kind": "原創觀念", "level": 1}, {"id": "c093", "topic": "線性映射、Kernel 與 Range", "en": "A linear map T is one-to-one if and only if ker(T)={0}.", "zh": "線性映射 T 是單射，若且唯若 ker(T)={0}。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 T(u)=T(v)，則 T(u−v)=0；kernel 只有 0 時 u=v，表示不同輸入不會撞到相同輸出。", "kind": "原創觀念", "level": 1}, {"id": "c094", "topic": "線性映射、Kernel 與 Range", "en": "A linear map T: V to W is onto if and only if R(T)=W.", "zh": "線性映射 T:V→W 是滿射，若且唯若 R(T)=W。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "onto/surjective 的意思是每個目標向量都能找到至少一個原像，不要求原像唯一。", "kind": "原創觀念", "level": 1}, {"id": "c095", "topic": "線性映射、Kernel 與 Range", "en": "For a linear map with finite-dimensional domain V, rank(T)+nullity(T)=dim V.", "zh": "若線性映射的定義域 V 有限維，則 rank(T)+nullity(T)=dim V。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "rank 是值域維度，nullity 是 kernel 維度；兩者相加等於輸入空間維度。", "kind": "原創觀念", "level": 1}, {"id": "c096", "topic": "線性映射、Kernel 與 Range", "en": "For a linear map T: R⁴ to R², nullity(T) must be at least two.", "zh": "對線性映射 T:R⁴→R²，nullity(T) 至少是 2。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "rank(T)≤2，因此 nullity(T)=4−rank(T)≥2；所以這種映射不可能單射。", "kind": "原創觀念", "level": 1}, {"id": "c097", "topic": "線性映射、Kernel 與 Range", "en": "A linear map from R² to R⁴ can be onto.", "zh": "線性映射 R²→R⁴ 可以是滿射。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "rank(T)≤2，無法張成 4 維陪域。輸入方向不夠，就不可能覆蓋全部輸出空間。", "kind": "原創觀念", "level": 1}, {"id": "c098", "topic": "線性映射、Kernel 與 Range", "en": "If V and W have the same finite dimension, a linear map T: V to W is injective if and only if it is surjective.", "zh": "若 V、W 有相同有限維度，線性映射 T:V→W 單射若且唯若滿射。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "單射表示 nullity=0，故 rank=dim V=dim W，也就是滿射。不同維度不能直接套用。", "kind": "原創觀念", "level": 1}, {"id": "c099", "topic": "線性映射、Kernel 與 Range", "en": "Every linear map sends linearly independent vectors to linearly independent vectors.", "zh": "每個線性映射都把線性獨立向量映成線性獨立向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "零映射會把所有向量映成 0。若額外已知 T 單射，才保證保持線性獨立。", "kind": "原創觀念", "level": 1}, {"id": "c100", "topic": "線性映射、Kernel 與 Range", "en": "An injective linear map preserves linear independence.", "zh": "單射線性映射保持線性獨立。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 ΣaᵢT(vᵢ)=0，則 T(Σaᵢvᵢ)=0；單射使 Σaᵢvᵢ=0，再由原組獨立得到所有係數為 0。", "kind": "原創觀念", "level": 2}, {"id": "c101", "topic": "線性映射、Kernel 與 Range", "en": "For a linear map T, if T(v₁),...,T(vₖ) are linearly independent, then v₁,...,vₖ are linearly independent.", "zh": "對線性映射 T，若像向量 T(v₁),…,T(vₖ) 線性獨立，則原向量 v₁,…,vₖ 也線性獨立。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "原向量若有非平凡零線性組合，套用 T 就會讓像向量也相依。此方向不需要 T 單射。", "kind": "原創觀念", "level": 2}, {"id": "c102", "topic": "線性映射、Kernel 與 Range", "en": "A linear map sends a spanning set of its domain to a spanning set of its range.", "zh": "線性映射會把定義域的張成組，映成值域的張成組。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 v=Σaᵢvᵢ，則 T(v)=ΣaᵢT(vᵢ)。注意張成的是 range，不一定是整個 codomain。", "kind": "原創觀念", "level": 1}, {"id": "c103", "topic": "線性映射、Kernel 與 Range", "en": "If AB=0, then R(B) is contained in N(A).", "zh": "若 AB=0，則 R(B) 包含於 N(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "任取 y∈R(B)，可寫 y=Bx，所以 Ay=ABx=0。B 的每個輸出都被 A 送到零。", "kind": "原創觀念", "level": 2}, {"id": "c104", "topic": "線性映射、Kernel 與 Range", "en": "For real n by n matrices A and B, if AB=0, then R(A) must be contained in N(B).", "zh": "對實 n×n 矩陣 A、B，若 AB=0，則 R(A) 必包含於 N(B)。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "AB=0 說的是先 B 後 A，因此應是 R(B)⊆N(A)。反方向需要 BA=0，且一般 AB=0 不推出 BA=0。 具體反例：A=[[1,0],[0,0]]、B=[[0,0],[1,0]]，則 AB=0，但 BA=B≠0，且 (1,0) 屬於 R(A) 卻不在 N(B)。", "kind": "原創觀念", "level": 2}, {"id": "c105", "topic": "線性映射、Kernel 與 Range", "en": "For composable linear maps S and T, ker(T) is contained in ker(S composed with T).", "zh": "對可合成的線性映射 S、T，ker(T) 包含於 ker(S∘T)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若 T(v)=0，則 S(T(v))=S(0)=0。先被 T 消成零的向量，經 S 後仍是零。", "kind": "原創觀念", "level": 2}, {"id": "c106", "topic": "座標、表示矩陣與維度", "en": "The coordinate vector [v]ᵦ depends on the chosen ordered basis B.", "zh": "座標向量 [v]ᵦ 取決於選用的有序基底 B。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "同一個幾何向量，在不同基底下需要不同係數。即使只交換基底順序，座標分量也會交換。", "kind": "原創觀念", "level": 1}, {"id": "c107", "topic": "座標、表示矩陣與維度", "en": "If B=(b₁,...,bₙ), then [v]ᵦ=(c₁,...,cₙ) transpose means v=c₁b₁+...+cₙbₙ.", "zh": "若 B=(b₁,…,bₙ)，[v]ᵦ=(c₁,…,cₙ)ᵀ 表示 v=c₁b₁+…+cₙbₙ。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "座標向量就是用指定基底表示 v 時的係數清單，通常依慣例寫成直行。", "kind": "原創觀念", "level": 1}, {"id": "c108", "topic": "座標、表示矩陣與維度", "en": "The map taking a vector to its coordinate vector in a fixed basis is a linear isomorphism.", "zh": "固定基底後，把向量轉成座標向量的映射是線性同構。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "加法與倍數對應係數的加法與倍數；基底表示存在且唯一，所以此映射同時滿射與單射。", "kind": "原創觀念", "level": 2}, {"id": "c109", "topic": "座標、表示矩陣與維度", "en": "A change-of-coordinate matrix between two bases of the same finite-dimensional space is invertible.", "zh": "同一有限維空間兩組基底間的座標轉換矩陣必可逆。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "可先把 B 座標轉成 C 座標，再轉回 B。反向轉換就是逆矩陣。", "kind": "原創觀念", "level": 1}, {"id": "c110", "topic": "座標、表示矩陣與維度", "en": "If P converts B-coordinates to C-coordinates, then [v]꜀ = P[v]ᵦ.", "zh": "若 P 把 B 座標轉成 C 座標，則 [v]꜀=P[v]ᵦ。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "先辨認矩陣的輸入與輸出。矩陣右側放輸入座標，等號左側是輸出座標；反方向使用 P⁻¹。", "kind": "原創觀念", "level": 1}, {"id": "c111", "topic": "座標、表示矩陣與維度", "en": "The columns of the matrix of T relative to domain basis B and codomain basis C are the C-coordinates of T(bⱼ).", "zh": "T 對定義域基底 B 與陪域基底 C 的表示矩陣，其第 j 欄是 T(bⱼ) 的 C 座標。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "第 j 個輸入基底向量的 B 座標是 eⱼ；矩陣乘 eⱼ 會選出第 j 欄，因此該欄就是像向量的座標。", "kind": "原創觀念", "level": 2}, {"id": "c112", "topic": "座標、表示矩陣與維度", "en": "Changing bases can change the rank of the matrix representing a fixed linear map.", "zh": "對固定線性映射改變基底，可能改變表示矩陣的秩。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "換基底相當於左右乘可逆矩陣，因此保持秩。rank 是映射本身的性質，不依賴座標選擇。", "kind": "原創觀念", "level": 1}, {"id": "c113", "topic": "座標、表示矩陣與維度", "en": "For finite-dimensional spaces V and W, the matrix of a linear map T: V to W has dim W rows and dim V columns.", "zh": "有限維空間間的線性映射 T:V→W，其表示矩陣有 dim W 個橫列、dim V 個直行。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "輸入座標長度是 dim V，輸出座標長度是 dim W，因此矩陣尺寸是「輸出維度 × 輸入維度」。", "kind": "原創觀念", "level": 1}, {"id": "c114", "topic": "座標、表示矩陣與維度", "en": "A linear map is completely determined by its values on a basis of the domain.", "zh": "只要指定定義域每個基底向量的像，就唯一決定一個線性映射。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "任何 v 都有唯一基底展開 v=Σcᵢbᵢ；線性性強迫 T(v)=ΣcᵢT(bᵢ)，所以其他輸出全部確定。", "kind": "原創觀念", "level": 1}, {"id": "c115", "topic": "座標、表示矩陣與維度", "en": "Two matrices representing the same endomorphism in two different bases are similar.", "zh": "同一線性自映射在兩組不同基底下的表示矩陣互為相似矩陣。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "若輸入和輸出都以同一組基底換成另一組，兩矩陣滿足 B=P⁻¹AP。一般不同輸入、輸出換基底則未必是相似。", "kind": "原創觀念", "level": 2}, {"id": "c116", "topic": "座標、表示矩陣與維度", "en": "The dimension of the space of all real m by n matrices is mn.", "zh": "所有 m×n 實矩陣構成的空間，其維度為 mn。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "每個位置可獨立指定數值。以每次只有一個位置為 1 的矩陣作基底，共有 mn 個。", "kind": "原創觀念", "level": 1}, {"id": "c117", "topic": "座標、表示矩陣與維度", "en": "The zero vector space has dimension one because it contains one vector.", "zh": "零向量空間 {0} 的維度是 1，因為它含有一個向量。", "options": ["True（正確）", "False（錯誤）"], "answer": [1], "explanation": "維度數的是基底向量數，不是集合元素數。{0} 的基底是空集合，因此維度為 0。", "kind": "原創觀念", "level": 1}, {"id": "c118", "topic": "座標、表示矩陣與維度", "en": "For real matrices A and B of compatible sizes, N(B) is contained in N(AB).", "zh": "對尺寸相容的實矩陣 A、B，N(B) 包含於 N(AB)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "Bx=0 立即推出 ABx=A0=0。注意先乘的是右側 B；不能無條件換成 N(A)⊆N(AB)。", "kind": "原創觀念", "level": 1}, {"id": "c119", "topic": "座標、表示矩陣與維度", "en": "For compatible matrices A and B, Col(AB) is contained in Col(A).", "zh": "對尺寸相容的矩陣 A、B，Col(AB) 包含於 Col(A)。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "AB 的每個直行都是 A 乘上 B 的某個直行，因此都是 A 各欄的線性組合。", "kind": "原創觀念", "level": 1}, {"id": "c120", "topic": "座標、表示矩陣與維度", "en": "A linear map between finite-dimensional vector spaces and its matrix representation have the same rank and nullity.", "zh": "有限維向量空間間的線性映射與其基底表示矩陣，有相同的秩與零度。", "options": ["True（正確）", "False（錯誤）"], "answer": [0], "explanation": "座標映射是同構，會保持子空間的維度。kernel 的向量與矩陣零空間中的座標一一對應；range 也同理。", "kind": "原創觀念", "level": 2}, {"id": "a001", "topic": "行列式", "en": "For a real n×n matrix A, which condition is equivalent to det(A) ≠ 0?", "zh": "對實 n×n 矩陣 A，何者等價於行列式非零？", "options": ["rank(A)=n", "trace(A)≠0", "Every entry is nonzero", "A is symmetric"], "answer": [0], "explanation": "方陣的行列式非零等價於可逆，也等價於滿秩 rank(A)=n。跡非零不足以保證可逆，例如 diag(1,0)。", "kind": "原創觀念", "level": 1}, {"id": "a002", "topic": "行列式", "en": "A 3×3 matrix A has determinant 2. What is det(3A)?", "zh": "3×3 矩陣 A 的行列式為 2，det(3A) 為何？", "options": ["6", "18", "54", "162"], "answer": [2], "explanation": "整個矩陣乘 3，代表三列各乘 3，所以 det(3A)=3³det(A)=54。一般公式為 det(cA)=cⁿdet(A)。", "kind": "原創觀念", "level": 1}, {"id": "a003", "topic": "行列式", "en": "Matrix B is obtained from A by swapping two rows. Which identity holds?", "zh": "B 由 A 交換兩列得到，何者成立？", "options": ["det(B)=det(A)", "det(B)=−det(A)", "det(B)=0", "det(B)=2det(A)"], "answer": [1], "explanation": "交換兩列使行列式變號；不是只把交換位置的元素變號。若原本行列式為零，變號後仍是零。", "kind": "原創觀念", "level": 1}, {"id": "a004", "topic": "行列式", "en": "B is obtained by adding 5 times row 1 of A to row 2. What happens to the determinant?", "zh": "將 A 的第一列五倍加至第二列得到 B，行列式如何改變？", "options": ["It is multiplied by 5", "It is unchanged", "It changes sign", "It becomes zero"], "answer": [1], "explanation": "以一列的倍數加到另一列不改變行列式。要區分「某列乘 5」會使行列式乘 5，而此處是倍加。", "kind": "原創觀念", "level": 1}, {"id": "a005", "topic": "行列式", "en": "For real square matrices A and B of the same size, which identity always holds?", "zh": "同階實方陣 A、B，下列恆等式何者必成立？", "options": ["det(A+B)=det(A)+det(B)", "det(AB)=det(A)det(B)", "det(A−B)=det(A)−det(B)", "det(A²)=2det(A)"], "answer": [1], "explanation": "行列式對乘積具有乘法性，不對矩陣加法具有一般的加法性。例如 A=B=I₂，det(A+B)=4，但 det(A)+det(B)=2。", "kind": "原創觀念", "level": 1}, {"id": "a006", "topic": "行列式", "en": "If A is invertible and det(A)=−4, find det(A⁻¹).", "zh": "A 可逆且 det(A)=−4，求逆矩陣的行列式。", "options": ["−4", "4", "−1/4", "1/4"], "answer": [2], "explanation": "由 AA⁻¹=I 及乘法性，det(A)det(A⁻¹)=1，因此取倒數得到 −1/4。", "kind": "原創觀念", "level": 1}, {"id": "a007", "topic": "行列式", "en": "A is upper triangular with diagonal entries 2, −3, and 4. Find det(A).", "zh": "上三角矩陣 A 對角元素為 2、−3、4，求行列式。", "options": ["3", "−24", "24", "Depends on off-diagonal entries"], "answer": [1], "explanation": "三角矩陣的行列式等於對角元素的乘積，所以是 2×(−3)×4=−24。非對角元素不影響此結果。", "kind": "原創觀念", "level": 1}, {"id": "a008", "topic": "行列式", "en": "For a real n×n matrix A, select ALL identities that always hold.", "zh": "對實 n×n 矩陣 A，選出所有必成立的等式（多選）。", "options": ["det(Aᵀ)=det(A)", "det(−A)=(−1)ⁿdet(A)", "det(A²)=det(A)²", "det(A+A)=2det(A)"], "answer": [0, 1, 2], "explanation": "轉置不改變行列式；負號由 n 列各提出一次；平方用乘法性。關於 det(A+A) 的敘述，正確公式應為 det(2A)=2ⁿdet(A)，一般不是兩倍。", "kind": "原創觀念", "level": 2, "multiple": true}, {"id": "a009", "topic": "行列式", "en": "A real 3×3 matrix satisfies Aᵀ=−A. What must be true?", "zh": "實 3×3 矩陣滿足 Aᵀ=−A，何者必真？", "options": ["det(A)=0", "det(A)=1", "A=0", "rank(A)=3"], "answer": [0], "explanation": "det(A)=det(Aᵀ)=det(−A)=−det(A)，因此 det(A)=0。所有奇數階反對稱實矩陣皆奇異，但矩陣本身不必為零。", "kind": "原創觀念", "level": 2}, {"id": "a010", "topic": "行列式", "en": "A is a 3×3 matrix with det(A)=5. Find det(adj(A)).", "zh": "3×3 矩陣 A 滿足 det(A)=5，求伴隨矩陣行列式。", "options": ["5", "15", "25", "125"], "answer": [2], "explanation": "A 可逆，因此 adj(A)=det(A)A⁻¹。取行列式得 5³/5=25；n 階的一般公式為 det(adj(A))=det(A)ⁿ⁻¹。", "kind": "原創觀念", "level": 2}, {"id": "a011", "topic": "特徵值與特徵向量", "en": "Which is the definition of an eigenvector of A associated with λ?", "zh": "A 對應特徵值 λ 的特徵向量定義是什麼？", "options": ["Av=λv with v≠0", "Av=λv with λ≠0", "Av=0 with v=0", "Aᵀv=v for every v"], "answer": [0], "explanation": "特徵向量必須非零，特徵值可以是零。若允許零向量，A0=λ0 對每個 λ 都成立，便失去辨別特徵值的意義。", "kind": "原創觀念", "level": 1}, {"id": "a012", "topic": "特徵值與特徵向量", "en": "If Av=λv and v≠0, which statement holds for A²?", "zh": "已知 Av=λv 且 v≠0，對 A² 何者成立？", "options": ["A²v=2λv", "A²v=λ²v", "A²v=λv always", "A²v=0 always"], "answer": [1], "explanation": "再作用一次 A：A²v=A(λv)=λAv=λ²v。相同的 v 是 A² 的特徵向量，對應 λ²。", "kind": "原創觀念", "level": 1}, {"id": "a013", "topic": "特徵值與特徵向量", "en": "If A is invertible and Av=λv with v≠0, which eigenvalue of A⁻¹ corresponds to v?", "zh": "A 可逆且 Av=λv，逆矩陣對同一向量的特徵值為何？", "options": ["−λ", "λ²", "1/λ", "λ+1"], "answer": [2], "explanation": "可逆保證 λ≠0。對等式左乘 A⁻¹，得 v=λA⁻¹v，所以 A⁻¹v=(1/λ)v。", "kind": "原創觀念", "level": 1}, {"id": "a014", "topic": "特徵值與特徵向量", "en": "The eigenvalues of a complex 3×3 matrix, counted with algebraic multiplicity, are 1, 2, and −4. Find its trace.", "zh": "複數 3×3 矩陣的特徵值（計入代數重數）為 1、2、−4，求跡。", "options": ["−8", "−1", "7", "Cannot be determined"], "answer": [1], "explanation": "跡等於全部特徵值的總和，包含代數重數，因此為 −1。這個公式不要求矩陣可對角化。", "kind": "原創觀念", "level": 1}, {"id": "a015", "topic": "特徵值與特徵向量", "en": "The eigenvalues of a complex 3×3 matrix are 1, 2, and −4, counted with multiplicity. Find its determinant.", "zh": "複數 3×3 矩陣的特徵值為 1、2、−4（計入重數），求行列式。", "options": ["−8", "−1", "8", "Cannot be determined"], "answer": [0], "explanation": "行列式等於全部特徵值的乘積，因此為 −8。不必另加可對角化的假設。", "kind": "原創觀念", "level": 1}, {"id": "a016", "topic": "特徵值與特徵向量", "en": "Eigenvectors corresponding to distinct eigenvalues are always linearly independent. True or false?", "zh": "不同特徵值對應的特徵向量一定線性獨立，對或錯？", "options": ["True", "False"], "answer": [0], "explanation": "這是不同特徵值的重要定理。不代表它們在一般矩陣下互相垂直；互相垂直需要對稱或 Hermitian 等額外條件。", "kind": "原創觀念", "level": 1}, {"id": "a017", "topic": "特徵值與特徵向量", "en": "For a real matrix A, if 2+3i is an eigenvalue, what must also be an eigenvalue over ℂ?", "zh": "實矩陣 A 在複數域有特徵值 2+3i，還必有哪個特徵值？", "options": ["−2+3i", "2−3i", "−2−3i", "3+2i"], "answer": [1], "explanation": "實矩陣的特徵多項式係數為實數，非實根必成共軛對，因此有 2−3i；重數也相同。", "kind": "原創觀念", "level": 2}, {"id": "a018", "topic": "特徵值與特徵向量", "en": "Which statement about A and Aᵀ always holds for square A?", "zh": "方陣 A 與 Aᵀ 的哪個敘述一定正確？", "options": ["They have the same eigenvectors", "They have the same characteristic polynomial", "They are equal", "Their null spaces are equal"], "answer": [1], "explanation": "det(tI−Aᵀ)=det((tI−A)ᵀ)=det(tI−A)，所以特徵多項式相同。特徵向量與零空間則不必相同。", "kind": "原創觀念", "level": 2}, {"id": "a019", "topic": "特徵值與特徵向量", "en": "If A²=A, what is the complete set of possible eigenvalue values across all such matrices?", "zh": "考慮所有滿足 A²=A 的矩陣，特徵值的所有可能取值所成集合是哪一個？", "options": ["{−1,1}", "{0,1}", "{0,2}", "All real numbers"], "answer": [1], "explanation": "對特徵向量套用 A²=A，得 λ²v=λv。v 非零故 λ(λ−1)=0，只有 0 或 1；不代表兩者一定都出現。", "kind": "原創觀念", "level": 1}, {"id": "a020", "topic": "特徵值與特徵向量", "en": "A complex square matrix satisfies A³=0. Which statement must hold?", "zh": "複數方陣滿足 A³=0，何者必真？", "options": ["A=0", "Every eigenvalue is zero", "A is invertible", "A is diagonalizable"], "answer": [1], "explanation": "若 Av=λv，則 A³v=λ³v=0，推出 λ=0。非零冪零矩陣可存在，也不會因全零特徵值而自動可對角化。", "kind": "原創觀念", "level": 2}, {"id": "a021", "topic": "對角化", "en": "A complex n×n matrix is diagonalizable if and only if it has how many linearly independent eigenvectors?", "zh": "複數 n×n 矩陣可對角化，等價於有多少個線性獨立特徵向量？", "options": ["1", "n", "n²", "rank(A)"], "answer": [1], "explanation": "可對角化就是可以選出一組由特徵向量構成的基底。把 n 個獨立特徵向量放成 P 的欄，即得 P⁻¹AP 為對角矩陣。", "kind": "原創觀念", "level": 1}, {"id": "a022", "topic": "對角化", "en": "A complex n×n matrix has n distinct eigenvalues. What follows?", "zh": "複數 n×n 矩陣有 n 個相異特徵值，可推出什麼？", "options": ["It is diagonalizable", "It is symmetric", "It is orthogonal", "It is singular"], "answer": [0], "explanation": "n 個相異特徵值能提供 n 個線性獨立的特徵向量，因此可對角化。但不保證對稱、正交或奇異。", "kind": "原創觀念", "level": 1}, {"id": "a023", "topic": "對角化", "en": "A matrix with repeated eigenvalues cannot be diagonalized. True or false?", "zh": "具有重複特徵值的矩陣無法對角化，對或錯？", "options": ["True", "False"], "answer": [1], "explanation": "重複特徵值不等於不能對角化。例如 I₂ 的特徵值 1 重複兩次，但它已經是對角矩陣。要比較幾何重數與代數重數。", "kind": "原創觀念", "level": 1}, {"id": "a024", "topic": "對角化", "en": "For an eigenvalue λ, what is its geometric multiplicity?", "zh": "特徵值 λ 的幾何重數是什麼？", "options": ["dim N(A−λI)", "Its multiplicity as a characteristic root", "rank(A−λI)", "trace(A−λI)"], "answer": [0], "explanation": "幾何重數是特徵空間的維度，即 dim N(A−λI)。代數重數則是 λ 在特徵多項式中作為根的重數。", "kind": "原創觀念", "level": 1}, {"id": "a025", "topic": "對角化", "en": "For an eigenvalue λ with algebraic multiplicity m, its geometric multiplicity g satisfies which bound?", "zh": "特徵值 λ 的代數重數為 m、幾何重數為 g，何者正確？", "options": ["0≤g<m", "1≤g≤m", "g≥m+1", "g=m always"], "answer": [1], "explanation": "既然 λ 是特徵值，就有非零特徵向量，所以 g 至少為 1；而幾何重數不超過代數重數。兩者不一定相等。", "kind": "原創觀念", "level": 1}, {"id": "a026", "topic": "對角化", "en": "Is A=[[1,1],[0,1]] diagonalizable over ℂ?", "zh": "A=[[1,1],[0,1]] 在複數域可對角化嗎？", "options": ["Yes, because its determinant is nonzero", "Yes, because its eigenvalues are real", "No, because dim N(A−I)=1", "No, because det(A)=0"], "answer": [2], "explanation": "唯一特徵值 1 的代數重數為 2，但 A−I 的零空間只有一維，無法湊出兩個獨立特徵向量。可逆不代表可對角化。", "kind": "原創觀念", "level": 2}, {"id": "a027", "topic": "對角化", "en": "If A=PDP⁻¹ with D diagonal, which formula is valid for positive integer k?", "zh": "若 A=PDP⁻¹ 且 D 對角，正整數 k 的矩陣冪怎麼算？", "options": ["Aᵏ=PDᵏP⁻¹", "Aᵏ=PᵏDᵏP⁻ᵏ", "Aᵏ=kPDP⁻¹", "Aᵏ=DPᵏD⁻¹"], "answer": [0], "explanation": "相鄰的 P⁻¹P 會抵消，所以 Aᵏ=PDᵏP⁻¹。矩陣乘法不可任意交換，不能把各因子直接各自取 k 次方。", "kind": "原創觀念", "level": 2}, {"id": "a028", "topic": "對角化", "en": "The real matrix [[0,−1],[1,0]] is diagonalizable over which field?", "zh": "實矩陣 [[0,−1],[1,0]] 在哪個數域可對角化？", "options": ["Over ℝ but not ℂ", "Over ℂ but not ℝ", "Over both", "Over neither"], "answer": [1], "explanation": "特徵多項式為 t²+1，在實數域沒有特徵值，所以無法實對角化；在複數域有相異特徵值 i、−i，因此可對角化。", "kind": "原創觀念", "level": 2}, {"id": "a029", "topic": "對角化", "en": "A complex n×n matrix is diagonalizable exactly when, for every eigenvalue, which condition holds?", "zh": "複數 n×n 矩陣可對角化，等價於每個特徵值滿足哪個條件？", "options": ["Geometric multiplicity equals algebraic multiplicity", "Geometric multiplicity is 1", "The eigenvalue is nonzero", "Algebraic multiplicity is at least 2"], "answer": [0], "explanation": "在複數域特徵多項式完全分解；每個特徵值的幾何重數都等於代數重數時，各特徵空間維度加總為 n，能構成特徵基底。", "kind": "原創觀念", "level": 2}, {"id": "a030", "topic": "對角化", "en": "If a complex matrix is both nilpotent and diagonalizable, what must it be?", "zh": "若複數矩陣同時冪零且可對角化，它一定是什麼？", "options": ["The zero matrix", "The identity matrix", "Any invertible matrix", "Any rank-one matrix"], "answer": [0], "explanation": "冪零矩陣的特徵值全部為 0。若又可對角化，D 必為零矩陣，所以 A=P0P⁻¹=0。", "kind": "原創觀念", "level": 2}, {"id": "a031", "topic": "相似矩陣", "en": "Which equation defines similarity of square matrices A and B?", "zh": "方陣 A、B 相似的定義是哪個等式？", "options": ["B=P⁻¹AP for some invertible P", "B=PA for any P", "B=Aᵀ", "B=A+I"], "answer": [0], "explanation": "相似是同一線性算子在不同基底下的矩陣表示，因此變換必須同時在左右使用互逆的 P⁻¹ 與 P。", "kind": "原創觀念", "level": 1}, {"id": "a032", "topic": "相似矩陣", "en": "If A and B are similar, select ALL quantities that must agree.", "zh": "若 A、B 相似，選出所有必相同的量（多選）。", "options": ["Rank", "Determinant", "Trace", "Individual matrix entries"], "answer": [0, 1, 2], "explanation": "左右乘可逆矩陣保留秩；det(P⁻¹AP)=det(A)；跡利用 tr(XY)=tr(YX) 保留。個別元素會隨基底改變。", "kind": "原創觀念", "level": 1, "multiple": true}, {"id": "a033", "topic": "相似矩陣", "en": "Two complex matrices with the same characteristic polynomial must be similar. True or false?", "zh": "兩個複數矩陣有相同特徵多項式，就一定相似，對或錯？", "options": ["True", "False"], "answer": [1], "explanation": "I₂ 與 [[1,1],[0,1]] 的特徵多項式同為 (t−1)²，但前者可對角化、後者不可，因此不相似。", "kind": "原創觀念", "level": 2}, {"id": "a034", "topic": "相似矩陣", "en": "If B=P⁻¹AP, what is B²?", "zh": "若 B=P⁻¹AP，B² 等於什麼？", "options": ["P⁻¹A²P", "P⁻²A²P²", "A²", "PAP⁻¹"], "answer": [0], "explanation": "B²=P⁻¹APP⁻¹AP=P⁻¹A²P。這說明相似關係會保留多項式運算的結構。", "kind": "原創觀念", "level": 2}, {"id": "a035", "topic": "相似矩陣", "en": "If A and B are similar and A is diagonalizable, which statement is true?", "zh": "A、B 相似且 A 可對角化，何者成立？", "options": ["B is diagonalizable", "B must already be diagonal", "B=A", "B must be symmetric"], "answer": [0], "explanation": "相似具有傳遞性。A 若相似於對角矩陣，B 又相似於 A，則 B 也相似於對角矩陣；但 B 本身不必對角。", "kind": "原創觀念", "level": 1}, {"id": "a036", "topic": "相似矩陣", "en": "Row-equivalent square matrices must have the same eigenvalues. True or false?", "zh": "列等價的方陣必具有相同特徵值，對或錯？", "options": ["True", "False"], "answer": [1], "explanation": "列運算保留秩與齊次方程解，但通常不保留特徵值。例如 I₂ 與 2I₂ 都可列化簡為 I₂，特徵值卻分別為 1 與 2。", "kind": "原創觀念", "level": 2}, {"id": "a037", "topic": "相似矩陣", "en": "If A and B are similar, what can be said about dim N(A−λI) and dim N(B−λI)?", "zh": "相似矩陣 A、B 的 λ 特徵空間維度有何關係？", "options": ["They are equal for every λ", "They sum to n", "They are equal only when λ=0", "No relation is guaranteed"], "answer": [0], "explanation": "B−λI=P⁻¹(A−λI)P，左右可逆乘法使秩相同，再用秩與零度定理得到零空間維度相同。", "kind": "原創觀念", "level": 2}, {"id": "a038", "topic": "相似矩陣", "en": "Which property is NOT necessarily preserved by general real similarity?", "zh": "一般實相似變換未必保留哪個性質？", "options": ["Being symmetric", "Being invertible", "Being nilpotent", "Being diagonalizable"], "answer": [0], "explanation": "一般相似未必保留對稱性。例如 A=diag(1,2)、P=[[1,1],[0,1]] 時，P⁻¹AP=[[1,−1],[0,2]] 不對稱。", "kind": "原創觀念", "level": 2}, {"id": "a039", "topic": "相似矩陣", "en": "Two diagonalizable complex n×n matrices have the same eigenvalues with the same algebraic multiplicities. What follows?", "zh": "兩個可對角化的複數 n×n 矩陣，特徵值及其代數重數都相同，可推出什麼？", "options": ["They are similar", "They are equal", "Their eigenvectors are identical", "They are unitary"], "answer": [0], "explanation": "兩者都可對角化成包含同一組特徵值的對角矩陣；調整基底順序可讓對角排列一致，所以兩者相似。", "kind": "原創觀念", "level": 2}, {"id": "a040", "topic": "相似矩陣", "en": "A is similar to the identity matrix Iₙ. What is A?", "zh": "A 與單位矩陣 Iₙ 相似，A 是什麼？", "options": ["A=Iₙ", "Any matrix with determinant 1", "Any invertible matrix", "Any matrix with eigenvalues 1"], "answer": [0], "explanation": "P⁻¹IₙP=P⁻¹P=Iₙ，所以單位矩陣只與自己相似。有全為 1 的特徵值仍不夠，例如非平凡 Jordan 區塊。", "kind": "原創觀念", "level": 2}, {"id": "a041", "topic": "正交與內積", "en": "For a real square matrix Q, which condition defines an orthogonal matrix?", "zh": "實方陣 Q 為正交矩陣的條件是什麼？", "options": ["QᵀQ=I", "Qᵀ=Q", "Q²=Q", "det(Q)=1"], "answer": [0], "explanation": "正交矩陣的欄向量構成標準正交基底，因此 QᵀQ=I。對稱矩陣是 Qᵀ=Q，兩者不同；正交矩陣行列式也可為 −1。", "kind": "原創觀念", "level": 1}, {"id": "a042", "topic": "正交與內積", "en": "If Q is a real orthogonal matrix, what is Q⁻¹?", "zh": "實正交矩陣 Q 的逆矩陣是什麼？", "options": ["Qᵀ", "−Q", "Q²", "I always"], "answer": [0], "explanation": "由 QᵀQ=I，Qᵀ 就是 Q 的逆矩陣。這是正交矩陣計算方便的重要原因。", "kind": "原創觀念", "level": 1}, {"id": "a043", "topic": "正交與內積", "en": "For a real orthogonal matrix Q and vector x, which equality always holds?", "zh": "實正交矩陣 Q 與向量 x，哪個等式必成立？", "options": ["‖Qx‖₂=‖x‖₂", "Qx=x", "Qx=−x", "‖Qx‖₂=0"], "answer": [0], "explanation": "‖Qx‖₂²=xᵀQᵀQx=xᵀx，所以正交變換保留長度，也保留內積與角度；不代表每個向量位置不變。", "kind": "原創觀念", "level": 1}, {"id": "a044", "topic": "正交與內積", "en": "What is the complete set of possible determinants of real orthogonal matrices?", "zh": "實正交矩陣行列式的所有可能取值所成集合是哪一個？", "options": ["{0,1}", "{−1,1}", "{1}", "All nonzero real numbers"], "answer": [1], "explanation": "取 det(QᵀQ)=det(I) 得 det(Q)²=1，因此為 ±1。旋轉常為 1，反射可為 −1。", "kind": "原創觀念", "level": 1}, {"id": "a045", "topic": "正交與內積", "en": "Any finite set of mutually orthogonal nonzero real vectors is linearly independent. True or false?", "zh": "有限個兩兩垂直且非零的實向量一定線性獨立，對或錯？", "options": ["True", "False"], "answer": [0], "explanation": "若 Σcᵢvᵢ=0，與 vⱼ 取內積後其餘項消失，留下 cⱼ‖vⱼ‖²=0。因 vⱼ 非零，所有係數都為零。", "kind": "原創觀念", "level": 1}, {"id": "a046", "topic": "正交與內積", "en": "For a subspace W of ℝⁿ with the Euclidean inner product, which identity is true?", "zh": "ℝⁿ 中採標準內積，子空間 W 的哪個等式正確？", "options": ["dim W+dim W⊥=n", "W=W⊥ always", "W∩W⊥=W", "dim W=dim W⊥ always"], "answer": [0], "explanation": "正交補提供剩下的獨立方向，所以維度相加為 n。兩者交集只有零向量，因為同時在兩者中的 x 滿足 xᵀx=0。", "kind": "原創觀念", "level": 1}, {"id": "a047", "topic": "正交與內積", "en": "For W⊆ℝⁿ a subspace, what is W∩W⊥?", "zh": "ℝⁿ 中子空間 W 與其正交補的交集為何？", "options": ["{0}", "W", "ℝⁿ", "The empty set"], "answer": [0], "explanation": "零向量一定在兩者內。若 x 同時屬於 W 與 W⊥，它必與自己垂直，故 ‖x‖²=0，只有 x=0。", "kind": "原創觀念", "level": 1}, {"id": "a048", "topic": "正交與內積", "en": "Applying Gram–Schmidt and then normalizing the resulting vectors, starting from linearly independent real vectors, produces what?", "zh": "對線性獨立向量執行 Gram–Schmidt 正交化並正規化，會得到什麼？", "options": ["An orthonormal basis for their span", "Eigenvectors of every matrix", "The standard basis necessarily", "A basis for all ℝⁿ necessarily"], "answer": [0], "explanation": "Gram–Schmidt 逐步扣除在先前方向上的投影，再除以長度。所得向量標準正交，且張成空間與原向量相同。", "kind": "原創觀念", "level": 1}, {"id": "a049", "topic": "正交與內積", "en": "Every real symmetric matrix admits which factorization?", "zh": "每個實對稱矩陣都具有哪個分解？", "options": ["A=QDQᵀ with Q orthogonal and D real diagonal", "A=Q with Q orthogonal", "A=LLᵀ with L invertible always", "A=PDP⁻¹ with D strictly positive always"], "answer": [0], "explanation": "實對稱矩陣的譜定理保證可正交對角化，特徵值皆為實數。但特徵值不必正，因此不能直接推得正定分解。", "kind": "原創觀念", "level": 2}, {"id": "a050", "topic": "正交與內積", "en": "For a real symmetric matrix, eigenvectors associated with distinct eigenvalues are what?", "zh": "實對稱矩陣中，不同特徵值對應的特徵向量有何關係？", "options": ["Orthogonal", "Parallel", "Equal in length", "All unit vectors"], "answer": [0], "explanation": "由 xᵀAy=(Ax)ᵀy 得 μxᵀy=λxᵀy。λ≠μ 時 xᵀy=0，因此垂直；長度則可任意縮放。", "kind": "原創觀念", "level": 2}, {"id": "a051", "topic": "投影矩陣", "en": "If u is a real unit vector, what is the orthogonal projection of x onto span{u}?", "zh": "u 是實單位向量，x 在 span{u} 上的正交投影為何？", "options": ["(uᵀx)u", "x−(uᵀx)u", "uᵀx", "‖x‖u"], "answer": [0], "explanation": "uᵀx 是 x 在單位方向 u 上的分量，乘回 u 得投影向量。x 減去該投影才是垂直於 u 的殘差。", "kind": "原創觀念", "level": 1}, {"id": "a052", "topic": "投影矩陣", "en": "For a nonzero real vector a, which matrix projects orthogonally onto span{a}?", "zh": "非零實向量 a，哪個矩陣代表投影至 span{a} 的正交投影？", "options": ["aaᵀ/(aᵀa)", "aᵀa", "aaᵀ always", "I−aaᵀ/(aᵀa)"], "answer": [0], "explanation": "投影公式是 a(aᵀx)/(aᵀa)，把 x 提到右邊即得到矩陣 aaᵀ/(aᵀa)。只有 a 是單位向量時才可省略分母。", "kind": "原創觀念", "level": 1}, {"id": "a053", "topic": "投影矩陣", "en": "A real square matrix P is an orthogonal projection matrix if and only if which conditions hold?", "zh": "實方陣 P 為正交投影矩陣的充要條件為何？", "options": ["P²=P and Pᵀ=P", "P²=P only", "Pᵀ=P only", "PᵀP=I"], "answer": [0], "explanation": "冪等 P²=P 表示投影後再投影不變；對稱 Pᵀ=P 保證是正交投影。僅冪等可能是斜投影，不能省略對稱條件。", "kind": "原創觀念", "level": 2}, {"id": "a054", "topic": "投影矩陣", "en": "For a real orthogonal projection matrix P onto a subspace W of ℝⁿ, what does I−P project onto?", "zh": "P 是到子空間 W 的正交投影矩陣，I−P 投影至何處？", "options": ["W⊥", "W", "All ℝⁿ", "The empty set"], "answer": [0], "explanation": "任意 x 分解成 Px+(I−P)x；前者在 W，後者在 W⊥。因此 I−P 是到 W 正交補的投影。", "kind": "原創觀念", "level": 1}, {"id": "a055", "topic": "投影矩陣", "en": "If columns of a real matrix Q are orthonormal, what projects orthogonally onto R(Q)?", "zh": "實矩陣 Q 的欄向量標準正交，哪個矩陣是投影至欄空間 R(Q) 的正交投影？", "options": ["QQᵀ", "QᵀQ", "Q²", "Q⁻¹"], "answer": [0], "explanation": "Q 可為 n×k 的長方矩陣。投影為 Q(Qᵀx)，所以矩陣是 QQᵀ；QᵀQ=Iₖ 位於係數空間，不是原空間投影。", "kind": "原創觀念", "level": 2}, {"id": "a056", "topic": "投影矩陣", "en": "If a real m×n matrix A has full column rank, which is the orthogonal projector onto R(A)?", "zh": "實 m×n 矩陣 A 滿欄秩，投影至 R(A) 的正交投影矩陣為何？", "options": ["A(AᵀA)⁻¹Aᵀ", "AᵀA", "A⁻¹", "Aᵀ(AAᵀ)⁻¹A"], "answer": [0], "explanation": "滿欄秩使 AᵀA 可逆。最小平方的投影點為 A x̂，代入 x̂=(AᵀA)⁻¹Aᵀb，即得到投影矩陣。", "kind": "原創觀念", "level": 2}, {"id": "a057", "topic": "投影矩陣", "en": "For a real orthogonal projector P, which relation holds between Px and (I−P)x?", "zh": "實正交投影 P 下，Px 與 (I−P)x 有何關係？", "options": ["They are orthogonal", "They are always equal", "They are always parallel", "Their lengths are equal"], "answer": [0], "explanation": "兩者內積為 xᵀPᵀ(I−P)x=xᵀ(P−P²)x=0。這依賴 P 對稱且冪等。", "kind": "原創觀念", "level": 2}, {"id": "a058", "topic": "投影矩陣", "en": "A real orthogonal projection matrix has rank 3. What is its trace?", "zh": "實正交投影矩陣秩為 3，其跡是多少？", "options": ["0", "1", "3", "Cannot be determined"], "answer": [2], "explanation": "投影的特徵值只有 0、1，且可對角化。秩是特徵值 1 的個數，跡也是這些 1 的總數，所以都是 3。", "kind": "原創觀念", "level": 2}, {"id": "a059", "topic": "投影矩陣", "en": "Which vector is the orthogonal projection of (2,0) onto span{(1,1)}?", "zh": "(2,0) 在 span{(1,1)} 上的正交投影為何？", "options": ["(1,1)", "(2,2)", "(1,−1)", "(0,0)"], "answer": [0], "explanation": "投影係數為 [(1,1)·(2,0)]/[(1,1)·(1,1)]=2/2=1，所以投影是 (1,1)，殘差 (1,−1) 與方向垂直。", "kind": "原創觀念", "level": 1}, {"id": "a060", "topic": "投影矩陣", "en": "For a real orthogonal projection P, select ALL statements that always hold.", "zh": "對實正交投影 P，選出所有必成立敘述（多選）。", "options": ["‖Px‖₂≤‖x‖₂ for every x", "R(P) is orthogonal to N(P)", "P²=P", "P is invertible"], "answer": [0, 1, 2], "explanation": "正交分解給出 ‖x‖²=‖Px‖²+‖(I−P)x‖²，故投影不增長度；像空間與核互相垂直。只有投影到全空間時 P=I 才可逆。", "kind": "原創觀念", "level": 2, "multiple": true}, {"id": "a061", "topic": "最小平方法", "en": "A least-squares solution of Ax=b minimizes which quantity?", "zh": "Ax=b 的最小平方解要最小化哪個量？", "options": ["‖Ax−b‖₂²", "‖x‖₂² only", "det(A)", "‖Aᵀx‖₂²"], "answer": [0], "explanation": "最小平方的目標是讓預測 Ax 與 b 的誤差平方和最小。它不直接要求 x 的長度最小；最小範數解是另一個附加條件。", "kind": "原創觀念", "level": 1}, {"id": "a062", "topic": "最小平方法", "en": "For real A and b, which equations characterize least-squares solutions?", "zh": "實矩陣 A 與向量 b，其最小平方解由哪組方程刻畫？", "options": ["AᵀAx=Aᵀb", "AAᵀx=b", "Ax=0", "Aᵀx=b"], "answer": [0], "explanation": "對 ‖Ax−b‖² 微分，梯度為 2Aᵀ(Ax−b)。令其為零得到正規方程，且凸二次函數使此條件充分必要。", "kind": "原創觀念", "level": 1}, {"id": "a063", "topic": "最小平方法", "en": "For real A and b, if x̂ is a least-squares solution, the residual b−Ax̂ is orthogonal to which space?", "zh": "實矩陣 A 與實向量 b，若 x̂ 為最小平方解，殘差 b−Ax̂ 垂直於哪個空間？", "options": ["R(A)", "N(A)", "R(Aᵀ) always", "The span of b always"], "answer": [0], "explanation": "正規方程等價於 Aᵀ(b−Ax̂)=0，所以殘差屬於 N(Aᵀ)=R(A)⊥，也就是與 A 的每個欄向量垂直。", "kind": "原創觀念", "level": 1}, {"id": "a064", "topic": "最小平方法", "en": "For a real m×n matrix A, the least-squares solution is unique for every b if and only if what holds?", "zh": "實 m×n 矩陣 A，對每個 b 都有唯一最小平方解的充要條件為何？", "options": ["rank(A)=n", "rank(A)=m", "m=n always", "b∈R(A)"], "answer": [0], "explanation": "唯一性需要 N(A)={0}，即滿欄秩。否則任一解加上非零核向量仍產生同一 Ax，因此也有相同誤差。", "kind": "原創觀念", "level": 2}, {"id": "a065", "topic": "最小平方法", "en": "If the columns of real A are linearly independent, which matrix must be invertible?", "zh": "實矩陣 A 的欄向量線性獨立，哪個矩陣一定可逆？", "options": ["AᵀA", "AAᵀ", "A itself even if rectangular", "A+Aᵀ"], "answer": [0], "explanation": "對非零 x，xᵀAᵀAx=‖Ax‖²>0，所以 AᵀA 正定且可逆。AAᵀ 在 A 為高矩陣時反而可能奇異。", "kind": "原創觀念", "level": 2}, {"id": "a066", "topic": "最小平方法", "en": "Can an inconsistent real system Ax=b have a least-squares solution?", "zh": "無解的實線性系統 Ax=b 能有最小平方解嗎？", "options": ["Yes, always in finite dimensions", "No", "Only if A is square", "Only if b=0"], "answer": [0], "explanation": "有限維下 R(A) 是閉子空間，b 在 R(A) 上必有正交投影，投影點可寫成 Ax̂，因此最小平方解一定存在。", "kind": "原創觀念", "level": 2}, {"id": "a067", "topic": "最小平方法", "en": "If x̂₁ and x̂₂ are least-squares solutions for the same A,b, which equality must hold?", "zh": "同一組 A、b 的兩個最小平方解 x̂₁、x̂₂，何者必成立？", "options": ["Ax̂₁=Ax̂₂", "x̂₁=x̂₂", "‖x̂₁‖=‖x̂₂‖", "x̂₁+x̂₂=0"], "answer": [0], "explanation": "投影點是唯一的，因此所有最小平方解產生相同的 Ax̂。兩個解之差可落在 N(A)，所以係數本身不一定唯一。", "kind": "原創觀念", "level": 2}, {"id": "a068", "topic": "最小平方法", "en": "If real A has orthonormal columns, its least-squares solution is what?", "zh": "實矩陣 A 的欄向量標準正交，其最小平方解為何？", "options": ["x̂=Aᵀb", "x̂=Ab", "x̂=b", "x̂=0"], "answer": [0], "explanation": "標準正交欄向量使 AᵀA=I。正規方程立刻化成 x̂=Aᵀb，且滿欄秩保證唯一。", "kind": "原創觀念", "level": 1}, {"id": "a069", "topic": "最小平方法", "en": "For A=[1;1;1] and b=[1;2;6], find the scalar least-squares solution x̂.", "zh": "A=[1;1;1]、b=[1;2;6]，純量最小平方解 x̂ 是多少？", "options": ["2", "3", "6", "9"], "answer": [1], "explanation": "正規方程給出 (1+1+1)x̂=1+2+6，因此 x̂=3。用常數擬合資料時，最佳常數是平均值。", "kind": "原創觀念", "level": 1}, {"id": "a070", "topic": "最小平方法", "en": "If b∈R(A), what is the minimum of ‖Ax−b‖₂²?", "zh": "若 b 屬於 A 的欄空間，最小平方誤差最小值為何？", "options": ["0", "1", "‖b‖₂² always", "rank(A)"], "answer": [0], "explanation": "b∈R(A) 表示存在 x 使 Ax=b，殘差即可為零。平方範數不可能為負，因此零就是最小值，但解仍可能不唯一。", "kind": "原創觀念", "level": 1}, {"id": "a071", "topic": "正定與半正定", "en": "A real symmetric matrix A is positive definite when which condition holds?", "zh": "實對稱矩陣 A 為正定的定義為何？", "options": ["xᵀAx>0 for every nonzero real x", "Every entry of A is positive", "det(A)>0 only", "trace(A)>0 only"], "answer": [0], "explanation": "正定關注的是所有非零方向的二次型，不是每一個元素。例如 I 有零元素仍為正定；全為正的元素也可能構成非正定矩陣。", "kind": "原創觀念", "level": 1}, {"id": "a072", "topic": "正定與半正定", "en": "A real symmetric matrix is positive definite if and only if its eigenvalues are what?", "zh": "實對稱矩陣正定，等價於特徵值滿足什麼條件？", "options": ["All strictly positive", "All nonnegative", "All nonzero", "Their sum is positive"], "answer": [0], "explanation": "正交對角化後 xᵀAx=Σλᵢyᵢ²，所以每個 λᵢ 必須嚴格大於零。非負只足以保證半正定。", "kind": "原創觀念", "level": 1}, {"id": "a073", "topic": "正定與半正定", "en": "For any real matrix A, which statement about AᵀA is always true?", "zh": "任意實矩陣 A，AᵀA 必有何性質？", "options": ["It is symmetric positive semidefinite", "It is always positive definite", "It is always invertible", "It is always diagonal"], "answer": [0], "explanation": "AᵀA 對稱，且 xᵀAᵀAx=‖Ax‖²≥0。若 A 有非零核向量，此二次型可等於零，所以未必正定。", "kind": "原創觀念", "level": 1}, {"id": "a074", "topic": "正定與半正定", "en": "When is AᵀA positive definite for a real m×n matrix A?", "zh": "實 m×n 矩陣 A，何時 AᵀA 正定？", "options": ["Exactly when A has full column rank", "Exactly when A has full row rank", "Whenever A≠0", "Whenever m<n"], "answer": [0], "explanation": "AᵀA 正定要求每個非零 x 都有 Ax≠0，等價於 N(A)={0}，也就是 rank(A)=n。", "kind": "原創觀念", "level": 2}, {"id": "a075", "topic": "正定與半正定", "en": "A real symmetric matrix has positive determinant. Must it be positive definite?", "zh": "實對稱矩陣行列式為正，一定正定嗎？", "options": ["Yes", "No"], "answer": [1], "explanation": "不一定，例如 −I₂ 的行列式是 1，但 xᵀ(−I₂)x=−‖x‖²<0，是負定。行列式只控制特徵值乘積。", "kind": "原創觀念", "level": 1}, {"id": "a076", "topic": "正定與半正定", "en": "For the real symmetric matrix [[a,b],[b,c]], which condition is equivalent to positive definiteness?", "zh": "實對稱矩陣 [[a,b],[b,c]]，正定的充要條件為何？", "options": ["a>0 and ac−b²>0", "a+c>0 only", "ac−b²>0 only", "b>0 and c>0"], "answer": [0], "explanation": "Sylvester 判別法要求所有順序主子式嚴格為正。二階情形就是第一個 a>0，以及完整行列式 ac−b²>0。", "kind": "原創觀念", "level": 2}, {"id": "a077", "topic": "正定與半正定", "en": "If A is real symmetric positive definite, what about A⁻¹?", "zh": "A 是實對稱正定矩陣，其逆矩陣有何性質？", "options": ["It is also symmetric positive definite", "It is negative definite", "It is singular", "It has zero eigenvalues"], "answer": [0], "explanation": "正定保證特徵值皆正，所以可逆；逆矩陣對應的特徵值是其倒數，仍全為正，且逆矩陣仍對稱。", "kind": "原創觀念", "level": 2}, {"id": "a078", "topic": "正定與半正定", "en": "If A and B are real symmetric positive definite of the same size, what must be positive definite?", "zh": "同階實對稱正定矩陣 A、B，下列何者必為正定？", "options": ["A+B", "A−B", "AB as a symmetric matrix always", "A−2B"], "answer": [0], "explanation": "對任何非零 x，xᵀ(A+B)x=xᵀAx+xᵀBx>0。AB 未必對稱，不能直接稱為實對稱正定矩陣。", "kind": "原創觀念", "level": 2}, {"id": "a079", "topic": "正定與半正定", "en": "A real symmetric matrix has eigenvalues −2, 0, and 5. How is its quadratic form classified?", "zh": "實對稱矩陣特徵值為 −2、0、5，其二次型屬於哪一類？", "options": ["Positive definite", "Positive semidefinite", "Negative semidefinite", "Indefinite"], "answer": [3], "explanation": "同時存在正、負特徵值，沿其特徵向量可得到正值與負值，因此為不定。含零特徵值不會改變此分類。", "kind": "原創觀念", "level": 1}, {"id": "a080", "topic": "正定與半正定", "en": "For a real symmetric positive semidefinite A, if xᵀAx=0, what follows?", "zh": "實對稱半正定矩陣 A，若 xᵀAx=0，可推出什麼？", "options": ["Ax=0", "x=0 necessarily", "A=0 necessarily", "Ax=x"], "answer": [0], "explanation": "正交對角化後 Σλᵢyᵢ²=0，各項皆非負，所以正特徵值對應分量全為零，得 Ax=0。若只是一般不定矩陣，結論不成立。", "kind": "原創觀念", "level": 3}, {"id": "a081", "topic": "奇異值分解", "en": "The singular values of a real m×n matrix A are derived from which matrix?", "zh": "實 m×n 矩陣 A 的奇異值由哪個矩陣求得？", "options": ["Square roots of eigenvalues of AᵀA, omitting n−m extra zeros if n>m", "The eigenvalues of A themselves", "The diagonal entries of A", "The roots of det(A)"], "answer": [0], "explanation": "AᵀA 對稱半正定，特徵值皆非負，取平方根得到奇異值；長方矩陣採 min(m,n) 個奇異值時省略額外的零值。", "kind": "原創觀念", "level": 1}, {"id": "a082", "topic": "奇異值分解", "en": "In a real SVD A=UΣVᵀ, what property do U and V have in the full SVD?", "zh": "實矩陣完整 SVD：A=UΣVᵀ，其中 U、V 有何性質？", "options": ["They are orthogonal matrices", "They are diagonal matrices", "They are equal", "They are positive definite"], "answer": [0], "explanation": "完整分解中 U 為 m×m、V 為 n×n 正交矩陣，Σ 為 m×n 非負對角形矩陣。U、V 不必相等。", "kind": "原創觀念", "level": 1}, {"id": "a083", "topic": "奇異值分解", "en": "The rank of A equals which quantity in its SVD?", "zh": "A 的秩等於 SVD 中哪個量？", "options": ["The number of positive singular values", "The sum of singular values", "The largest singular value", "The number of columns of U"], "answer": [0], "explanation": "左右正交乘法不改變秩，而 Σ 的秩就是非零對角元素數量。奇異值非負，所以非零即正。", "kind": "原創觀念", "level": 1}, {"id": "a084", "topic": "奇異值分解", "en": "What is the largest singular value of diag(−3,2)?", "zh": "diag(−3,2) 的最大奇異值為何？", "options": ["−3", "2", "3", "9"], "answer": [2], "explanation": "AᵀA=diag(9,4)，特徵值平方根為 3、2。奇異值永遠非負，不可直接把 −3 當奇異值。", "kind": "原創觀念", "level": 1}, {"id": "a085", "topic": "奇異值分解", "en": "For a real matrix A with singular values σᵢ, what is ‖A‖F²?", "zh": "實矩陣 A 的奇異值為 σᵢ，Frobenius 範數平方為何？", "options": ["Σσᵢ²", "Σσᵢ", "max σᵢ", "Πσᵢ"], "answer": [0], "explanation": "‖A‖F² 等於所有元素平方和，也等於 tr(AᵀA)，因此等於 AᵀA 全部特徵值之和，即 Σσᵢ²。", "kind": "原創觀念", "level": 2}, {"id": "a086", "topic": "奇異值分解", "en": "For a real matrix A, its induced Euclidean norm ‖A‖₂ equals what?", "zh": "實矩陣 A 的誘導二範數等於什麼？", "options": ["Its largest singular value", "Its largest eigenvalue always", "Its trace", "Its rank"], "answer": [0], "explanation": "‖A‖₂=max_{‖x‖₂=1}‖Ax‖₂，是最大拉伸比例，等於最大奇異值。非對稱矩陣不能直接用最大特徵值代替。", "kind": "原創觀念", "level": 2}, {"id": "a087", "topic": "奇異值分解", "en": "In a full real SVD A=UΣVᵀ, which right singular vectors span N(A)?", "zh": "實矩陣的完整 SVD：A=UΣVᵀ 中，哪些右奇異向量張成 N(A)？", "options": ["Those whose corresponding columns of Σ are zero", "Those associated with positive singular values", "All columns of U", "Only the first column of V"], "answer": [0], "explanation": "A vⱼ=UΣeⱼ。若 Σ 對應欄為零，就有 Avⱼ=0；包含寬矩陣的額外零欄。所有這些 V 欄向量組成核的基底。", "kind": "原創觀念", "level": 2}, {"id": "a088", "topic": "奇異值分解", "en": "Does every real rectangular matrix admit an SVD?", "zh": "每個實長方矩陣都有奇異值分解嗎？", "options": ["Yes", "No, only square matrices", "No, only full-rank matrices", "No, only symmetric matrices"], "answer": [0], "explanation": "SVD 適用於任何實矩陣，包括長方、秩不足與零矩陣。它不像特徵對角化需要方陣且有足夠特徵向量。", "kind": "原創觀念", "level": 1}, {"id": "a089", "topic": "奇異值分解", "en": "The Moore–Penrose pseudoinverse uses which operation on positive singular values?", "zh": "Moore–Penrose 偽逆對正奇異值做什麼操作？", "options": ["Replace each by its reciprocal", "Negate each", "Square each", "Replace each by zero"], "answer": [0], "explanation": "若 A=UΣVᵀ，則 A⁺=VΣ⁺Uᵀ。Σ⁺ 轉置尺寸並將正奇異值取倒數，零值仍保留零，避免除以零。", "kind": "原創觀念", "level": 2}, {"id": "a090", "topic": "奇異值分解", "en": "For any real A and b, what special solution does A⁺b provide?", "zh": "任意實 A、b，A⁺b 提供哪種特殊解？", "options": ["The least-squares solution of minimum Euclidean norm", "An exact solution of Ax=b always", "The unique least-squares solution always", "A vector in N(A) always"], "answer": [0], "explanation": "即使 Ax=b 不相容，A⁺b 仍為最小平方解；若最小平方解不唯一，它是其中二範數最小者。只有 b∈R(A) 才保證精確解。", "kind": "原創觀念", "level": 2}, {"id": "a091", "topic": "Jordan 與最小多項式", "en": "Over ℂ, the minimal polynomial mA(t) is defined as which polynomial?", "zh": "複數域上，矩陣 A 的最小多項式 mA(t) 如何定義？", "options": ["The monic polynomial of least degree satisfying mA(A)=0", "The characteristic polynomial in every case", "The polynomial with the fewest nonzero coefficients", "Any polynomial p with p(0)=0"], "answer": [0], "explanation": "最小多項式要求首一、代入矩陣後為零，且次數最小。它不一定等於特徵多項式，例如 Iₙ 的最小多項式只有 t−1。", "kind": "原創觀念", "level": 2}, {"id": "a092", "topic": "Jordan 與最小多項式", "en": "Which relation between the minimal and characteristic polynomials always holds?", "zh": "最小多項式與特徵多項式必有何關係？", "options": ["The minimal polynomial divides the characteristic polynomial", "The characteristic polynomial divides the minimal polynomial always", "They are always equal", "They have disjoint roots"], "answer": [0], "explanation": "Cayley–Hamilton 定理保證特徵多項式代入 A 為零，而最小多項式整除所有使 A 歸零的多項式，因此整除特徵多項式。", "kind": "原創觀念", "level": 2}, {"id": "a093", "topic": "Jordan 與最小多項式", "en": "A complex matrix is diagonalizable if and only if its minimal polynomial has what property?", "zh": "複數矩陣可對角化，等價於其最小多項式有何性質？", "options": ["It has no repeated roots", "It has degree n", "Its constant term is zero", "It has only positive roots"], "answer": [0], "explanation": "複數域多項式可完全分解。最小多項式各一次因子不重複，等價於每個 Jordan 區塊大小都是 1，也就是可對角化。", "kind": "原創觀念", "level": 3}, {"id": "a094", "topic": "Jordan 與最小多項式", "en": "What is the minimal polynomial of A=λIₙ for n≥1?", "zh": "n≥1，純量矩陣 A=λIₙ 的最小多項式是什麼？", "options": ["t−λ", "(t−λ)ⁿ always", "tⁿ", "1"], "answer": [0], "explanation": "A−λI=0，所以一次多項式 t−λ 即可使 A 歸零。非零常數多項式無法使非零維度的單位矩陣變零，因此一次已最小。", "kind": "原創觀念", "level": 2}, {"id": "a095", "topic": "Jordan 與最小多項式", "en": "For a Jordan block Jk(λ) of size k, its minimal polynomial is what?", "zh": "大小為 k 的 Jordan 區塊 Jk(λ)，最小多項式為何？", "options": ["(t−λ)ᵏ", "t−λ always", "tᵏ−λ", "tᵏ+λ"], "answer": [0], "explanation": "Jk(λ)−λI 是上移的冪零矩陣，第 k 次方才首次為零，所以最小多項式中該因子的次數為 k。", "kind": "原創觀念", "level": 3}, {"id": "a096", "topic": "Jordan 與最小多項式", "en": "For a complex matrix, the number of Jordan blocks associated with λ equals what?", "zh": "複數矩陣中，特徵值 λ 所對應 Jordan 區塊的數量等於什麼？", "options": ["dim N(A−λI)", "The algebraic multiplicity always", "rank(A−λI)", "The largest block size"], "answer": [0], "explanation": "每個 λ 的 Jordan 區塊恰提供一個獨立的普通特徵向量，因此區塊數就是幾何重數 dim N(A−λI)。", "kind": "原創觀念", "level": 3}, {"id": "a097", "topic": "Jordan 與最小多項式", "en": "For a complex matrix, the sum of sizes of Jordan blocks associated with λ equals what?", "zh": "複數矩陣中，λ 對應各 Jordan 區塊大小總和等於什麼？", "options": ["The algebraic multiplicity of λ", "The geometric multiplicity always", "dim N(A)", "The largest block size"], "answer": [0], "explanation": "每個大小 k 的 λ 區塊對特徵多項式貢獻 (t−λ)ᵏ，所以所有區塊大小總和就是 λ 的代數重數。", "kind": "原創觀念", "level": 3}, {"id": "a098", "topic": "Jordan 與最小多項式", "en": "If mA(t)=(t−2)³(t+1), what is the largest Jordan block size for eigenvalue 2?", "zh": "若最小多項式為 (t−2)³(t+1)，特徵值 2 的最大 Jordan 區塊有多大？", "options": ["1", "2", "3", "4"], "answer": [2], "explanation": "最小多項式中 (t−λ) 的指數是 λ 對應最大 Jordan 區塊大小。因此 2 的最大區塊為 3；不是說全部區塊總大小必為 3。", "kind": "原創觀念", "level": 3}, {"id": "a099", "topic": "Jordan 與最小多項式", "en": "A nilpotent 4×4 complex matrix has Jordan block sizes 3 and 1. What is its rank?", "zh": "4×4 複數冪零矩陣的 Jordan 區塊大小為 3、1，其秩為何？", "options": ["1", "2", "3", "4"], "answer": [1], "explanation": "零特徵值的大小 k Jordan 區塊秩為 k−1，因此總秩為 (3−1)+(1−1)=2；亦可由零度等於區塊數 2 推得。", "kind": "原創觀念", "level": 3}, {"id": "a100", "topic": "Jordan 與最小多項式", "en": "A complex 3×3 matrix has characteristic polynomial (t−1)³ and dim N(A−I)=2. Which Jordan block sizes occur for λ=1?", "zh": "複數 3×3 矩陣特徵多項式為 (t−1)³，且 dim N(A−I)=2，Jordan 區塊大小如何分配？", "options": ["3", "2 and 1", "1, 1, and 1", "Cannot be determined"], "answer": [1], "explanation": "代數重數 3 表示區塊大小總和為 3；幾何重數 2 表示剛好兩個區塊。因此只能分成 2+1，也可知道不可對角化。", "kind": "原創觀念", "level": 3}, {"id": "v001", "topic": "英文名詞", "en": "What does “rank” mean in linear algebra?", "zh": "線性代數中「rank」的中文意思是什麼？", "options": ["秩", "古典伴隨矩陣", "增廣矩陣", "可對角化"], "answer": [0], "explanation": "rank(A)=dim Col(A)=dim Row(A)，等於 pivot 數；不是非零元素數。", "kind": "名詞辨識", "level": 1}, {"id": "v002", "topic": "英文名詞", "en": "What does “nullity” mean in linear algebra?", "zh": "線性代數中「nullity」的中文意思是什麼？", "options": ["至多", "奇異", "相似", "零度"], "answer": [3], "explanation": "nullity(A)=dim N(A)，等於自由變數數；A 有 n 個 column 時為 n−rank(A)。", "kind": "名詞辨識", "level": 1}, {"id": "v003", "topic": "英文名詞", "en": "What does “kernel” mean in linear algebra?", "zh": "線性代數中「kernel」的中文意思是什麼？", "options": ["線性轉換", "核空間", "行列式", "投影"], "answer": [1], "explanation": "ker(T)=N(T)={v∈V:T(v)=0}。收集被映成零的輸入。", "kind": "名詞辨識", "level": 1}, {"id": "v004", "topic": "英文名詞", "en": "What does “range” mean in linear algebra?", "zh": "線性代數中「range」的中文意思是什麼？", "options": ["存在至少一個", "像空間", "子空間", "陪域"], "answer": [1], "explanation": "R(T)=Im(T)={T(v):v∈V}。所有實際能得到的輸出，可能只是陪域的一部分。", "kind": "名詞辨識", "level": 1}, {"id": "v005", "topic": "英文名詞", "en": "What does “domain” mean in linear algebra?", "zh": "線性代數中「domain」的中文意思是什麼？", "options": ["厄米矩陣", "定義域", "代數重數", "張成空間"], "answer": [1], "explanation": "T:V→W 的 V，是允許輸入的空間。", "kind": "名詞辨識", "level": 1}, {"id": "v006", "topic": "英文名詞", "en": "What does “codomain” mean in linear algebra?", "zh": "線性代數中「codomain」的中文意思是什麼？", "options": ["線性相依", "直和", "陪域", "子空間"], "answer": [2], "explanation": "T:V→W 的 W，是預先指定的輸出所在空間，不一定等於 range。", "kind": "名詞辨識", "level": 1}, {"id": "v007", "topic": "英文名詞", "en": "What does “column space” mean in linear algebra?", "zh": "線性代數中「column space」的中文意思是什麼？", "options": ["非零解", "直行空間", "零度", "行列式"], "answer": [1], "explanation": "Col(A) 由 A 的直向 column 所張成；m×n 矩陣的 Col(A)⊆ℝᵐ。 對線性映射 x↦Ax，它也就是像空間 R(A)。", "kind": "名詞辨識", "level": 1}, {"id": "v008", "topic": "英文名詞", "en": "What does “row space” mean in linear algebra?", "zh": "線性代數中「row space」的中文意思是什麼？", "options": ["共軛轉置", "直和", "最小多項式", "橫列空間"], "answer": [3], "explanation": "Row(A) 由 A 的橫向 row 所張成；m×n 矩陣的 Row(A)⊆ℝⁿ。", "kind": "名詞辨識", "level": 1}, {"id": "v009", "topic": "英文名詞", "en": "What does “null space” mean in linear algebra?", "zh": "線性代數中「null space」的中文意思是什麼？", "options": ["正交", "陪域", "零空間", "冪等"], "answer": [2], "explanation": "N(A)={x:Ax=0}⊆ℝⁿ；不是等於數字 0。 它也稱為核空間 kernel。", "kind": "名詞辨識", "level": 1}, {"id": "v010", "topic": "英文名詞", "en": "What does “left null space” mean in linear algebra?", "zh": "線性代數中「left null space」的中文意思是什麼？", "options": ["左零空間", "線性組合", "子空間之和", "張成空間"], "answer": [0], "explanation": "對實 m×n 矩陣 A，左零空間為 N(Aᵀ)⊆ℝᵐ，與 Col(A) 正交。複數內積情況改用共軛轉置 A*。", "kind": "名詞辨識", "level": 1}, {"id": "v011", "topic": "英文名詞", "en": "What does “span” mean in linear algebra?", "zh": "線性代數中「span」的中文意思是什麼？", "options": ["充分條件", "正交矩陣", "奇異", "張成空間"], "answer": [3], "explanation": "span{v₁,…,vₖ} 是所有線性組合 c₁v₁+⋯+cₖvₖ；係數各自任意。", "kind": "名詞辨識", "level": 1}, {"id": "v012", "topic": "英文名詞", "en": "What does “linear combination” mean in linear algebra?", "zh": "線性代數中「linear combination」的中文意思是什麼？", "options": ["餘因子", "子空間之和", "雙射", "線性組合"], "answer": [3], "explanation": "c₁v₁+⋯+cₖvₖ，係數來自指定純量域。", "kind": "名詞辨識", "level": 1}, {"id": "v013", "topic": "英文名詞", "en": "What does “linearly independent” mean in linear algebra?", "zh": "線性代數中「linearly independent」的中文意思是什麼？", "options": ["正交", "基底", "交集", "線性獨立"], "answer": [3], "explanation": "c₁v₁+⋯+cₖvₖ=0 只允許所有 cᵢ=0。", "kind": "名詞辨識", "level": 1}, {"id": "v014", "topic": "英文名詞", "en": "What does “linearly dependent” mean in linear algebra?", "zh": "線性代數中「linearly dependent」的中文意思是什麼？", "options": ["線性相依", "線性獨立", "主元", "唯一"], "answer": [0], "explanation": "存在不全為零的係數，使線性組合等於零。", "kind": "名詞辨識", "level": 1}, {"id": "v015", "topic": "英文名詞", "en": "What does “basis” mean in linear algebra?", "zh": "線性代數中「basis」的中文意思是什麼？", "options": ["最小平方法", "正規方程式", "正交", "基底"], "answer": [3], "explanation": "同時線性獨立且張成整個空間的一組向量。", "kind": "名詞辨識", "level": 1}, {"id": "v016", "topic": "英文名詞", "en": "What does “dimension” mean in linear algebra?", "zh": "線性代數中「dimension」的中文意思是什麼？", "options": ["維度", "自由變數", "若且唯若／充要", "零解"], "answer": [0], "explanation": "有限維空間任一基底的向量個數；維度是數字，基底是向量集合。", "kind": "名詞辨識", "level": 1}, {"id": "v017", "topic": "英文名詞", "en": "What does “subspace” mean in linear algebra?", "zh": "線性代數中「subspace」的中文意思是什麼？", "options": ["可對角化", "轉置", "投影", "子空間"], "answer": [3], "explanation": "包含零向量且對加法與純量乘法封閉的子集合。", "kind": "名詞辨識", "level": 1}, {"id": "v018", "topic": "英文名詞", "en": "What does “intersection” mean in linear algebra?", "zh": "線性代數中「intersection」的中文意思是什麼？", "options": ["像空間", "交集", "非零解", "零解"], "answer": [1], "explanation": "U∩W 同時屬於 U 與 W 的向量；兩子空間交集仍是子空間。", "kind": "名詞辨識", "level": 1}, {"id": "v019", "topic": "英文名詞", "en": "What does “sum of subspaces” mean in linear algebra?", "zh": "線性代數中「sum of subspaces」的中文意思是什麼？", "options": ["子空間之和", "主元", "至多", "零空間"], "answer": [0], "explanation": "U+W={u+w:u∈U,w∈W}；通常不是 U∪W。", "kind": "名詞辨識", "level": 1}, {"id": "v020", "topic": "英文名詞", "en": "What does “direct sum” mean in linear algebra?", "zh": "線性代數中「direct sum」的中文意思是什麼？", "options": ["增廣矩陣", "相似", "維度", "直和"], "answer": [3], "explanation": "U⊕W 表示 U+W 且 U∩W={0}，每個向量分解唯一。", "kind": "名詞辨識", "level": 1}, {"id": "v021", "topic": "英文名詞", "en": "What does “linear transformation” mean in linear algebra?", "zh": "線性代數中「linear transformation」的中文意思是什麼？", "options": ["線性轉換", "特徵多項式", "至多", "冪等"], "answer": [0], "explanation": "T(au+bv)=aT(u)+bT(v)，必有 T(0)=0，但只滿足 T(0)=0 還不夠。", "kind": "名詞辨識", "level": 1}, {"id": "v022", "topic": "英文名詞", "en": "What does “one-to-one” mean in linear algebra?", "zh": "線性代數中「one-to-one」的中文意思是什麼？", "options": ["存在至少一個", "單射", "雙射", "像空間"], "answer": [1], "explanation": "不同輸入必有不同輸出；線性映射等價於 ker(T)={0}。", "kind": "名詞辨識", "level": 1}, {"id": "v023", "topic": "英文名詞", "en": "What does “onto” mean in linear algebra?", "zh": "線性代數中「onto」的中文意思是什麼？", "options": ["酉矩陣", "滿射", "奇異值", "雙射"], "answer": [1], "explanation": "每個陪域向量都有原像，即 R(T)=W。", "kind": "名詞辨識", "level": 1}, {"id": "v024", "topic": "英文名詞", "en": "What does “bijective” mean in linear algebra?", "zh": "線性代數中「bijective」的中文意思是什麼？", "options": ["唯一", "陪域", "雙射", "酉矩陣"], "answer": [2], "explanation": "同時單射與滿射。", "kind": "名詞辨識", "level": 1}, {"id": "v025", "topic": "英文名詞", "en": "What does “isomorphism” mean in linear algebra?", "zh": "線性代數中「isomorphism」的中文意思是什麼？", "options": ["直和", "同構", "跡", "非奇異"], "answer": [1], "explanation": "可逆的線性映射；有限維同一純量域的空間同構當且僅當維度相同。", "kind": "名詞辨識", "level": 1}, {"id": "v026", "topic": "英文名詞", "en": "What does “consistent” mean in linear algebra?", "zh": "線性代數中「consistent」的中文意思是什麼？", "options": ["有解／相容", "奇異", "維度", "唯一解"], "answer": [0], "explanation": "方程組至少有一個解，不代表解唯一。", "kind": "名詞辨識", "level": 1}, {"id": "v027", "topic": "英文名詞", "en": "What does “inconsistent” mean in linear algebra?", "zh": "線性代數中「inconsistent」的中文意思是什麼？", "options": ["無解／不相容", "半正定", "主元", "線性獨立"], "answer": [0], "explanation": "方程組不存在任何解。", "kind": "名詞辨識", "level": 1}, {"id": "v028", "topic": "英文名詞", "en": "What does “homogeneous system” mean in linear algebra?", "zh": "線性代數中「homogeneous system」的中文意思是什麼？", "options": ["正定", "齊次方程組", "增廣矩陣", "雙射"], "answer": [1], "explanation": "Ax=0，必有零解；是否有非零解取決於 nullity。", "kind": "名詞辨識", "level": 1}, {"id": "v029", "topic": "英文名詞", "en": "What does “trivial solution” mean in linear algebra?", "zh": "線性代數中「trivial solution」的中文意思是什麼？", "options": ["自由變數", "冪等", "零解", "厄米矩陣"], "answer": [2], "explanation": "齊次方程的 x=0。", "kind": "名詞辨識", "level": 1}, {"id": "v030", "topic": "英文名詞", "en": "What does “nontrivial solution” mean in linear algebra?", "zh": "線性代數中「nontrivial solution」的中文意思是什麼？", "options": ["冪等", "非零解", "有解／相容", "正交"], "answer": [1], "explanation": "齊次方程中 x≠0 的解；不是指每個分量都非零。", "kind": "名詞辨識", "level": 1}, {"id": "v031", "topic": "英文名詞", "en": "What does “augmented matrix” mean in linear algebra?", "zh": "線性代數中「augmented matrix」的中文意思是什麼？", "options": ["增廣矩陣", "零解", "核空間", "正交矩陣"], "answer": [0], "explanation": "增廣矩陣 [A|b] 是把右端向量 b 接在係數矩陣 A 的右邊。Ax=b 有解的充要條件為 rank(A)=rank([A|b])。", "kind": "名詞辨識", "level": 1}, {"id": "v032", "topic": "英文名詞", "en": "What does “pivot” mean in linear algebra?", "zh": "線性代數中「pivot」的中文意思是什麼？", "options": ["直和", "像空間", "主元", "存在至少一個"], "answer": [2], "explanation": "階梯形矩陣每個非零 row 的領頭非零位置；pivot 數等於 rank。", "kind": "名詞辨識", "level": 1}, {"id": "v033", "topic": "英文名詞", "en": "What does “free variable” mean in linear algebra?", "zh": "線性代數中「free variable」的中文意思是什麼？", "options": ["像空間", "自由變數", "至少", "可逆"], "answer": [1], "explanation": "非 pivot column 對應的未知數，數目為 n−rank(A)。", "kind": "名詞辨識", "level": 1}, {"id": "v034", "topic": "英文名詞", "en": "What does “row equivalent” mean in linear algebra?", "zh": "線性代數中「row equivalent」的中文意思是什麼？", "options": ["必要條件", "列等價（橫向運算）", "餘因子", "陪域"], "answer": [1], "explanation": "可用初等 row operations 互相轉換；保留 row space 與 null space，不一定保留 column space。", "kind": "名詞辨識", "level": 1}, {"id": "v035", "topic": "英文名詞", "en": "What does “reduced row echelon form” mean in linear algebra?", "zh": "線性代數中「reduced row echelon form」的中文意思是什麼？", "options": ["充分條件", "最簡列階梯形", "陪域", "互異"], "answer": [1], "explanation": "RREF 的 pivot 為 1 且所在 column 其他元素為 0；每個矩陣的 RREF 唯一。", "kind": "名詞辨識", "level": 1}, {"id": "v036", "topic": "英文名詞", "en": "What does “invertible” mean in linear algebra?", "zh": "線性代數中「invertible」的中文意思是什麼？", "options": ["半正定", "奇異", "可逆", "線性組合"], "answer": [2], "explanation": "方陣存在雙邊反矩陣 A⁻¹；等價於滿秩、det(A)≠0。", "kind": "名詞辨識", "level": 1}, {"id": "v037", "topic": "英文名詞", "en": "What does “singular” mean in linear algebra?", "zh": "線性代數中「singular」的中文意思是什麼？", "options": ["相似", "線性相依", "共軛轉置", "奇異"], "answer": [3], "explanation": "不可逆的方陣；det(A)=0。", "kind": "名詞辨識", "level": 1}, {"id": "v038", "topic": "英文名詞", "en": "What does “nonsingular” mean in linear algebra?", "zh": "線性代數中「nonsingular」的中文意思是什麼？", "options": ["酉矩陣", "幾何重數", "非奇異", "投影"], "answer": [2], "explanation": "可逆方陣；不要和非零矩陣混淆。", "kind": "名詞辨識", "level": 1}, {"id": "v039", "topic": "英文名詞", "en": "What does “transpose” mean in linear algebra?", "zh": "線性代數中「transpose」的中文意思是什麼？", "options": ["相似", "轉置", "特徵向量", "幾何重數"], "answer": [1], "explanation": "Aᵀ 交換 row 與 column；(AB)ᵀ=BᵀAᵀ。", "kind": "名詞辨識", "level": 1}, {"id": "v040", "topic": "英文名詞", "en": "What does “conjugate transpose” mean in linear algebra?", "zh": "線性代數中「conjugate transpose」的中文意思是什麼？", "options": ["線性轉換", "列等價（橫向運算）", "線性組合", "共軛轉置"], "answer": [3], "explanation": "A* 先取複共軛再轉置；複數內積需要共軛。", "kind": "名詞辨識", "level": 1}, {"id": "v041", "topic": "英文名詞", "en": "What does “trace” mean in linear algebra?", "zh": "線性代數中「trace」的中文意思是什麼？", "options": ["共軛轉置", "行列式", "餘因子", "跡"], "answer": [3], "explanation": "方陣對角元素之和；也等於含代數重數的特徵值總和。", "kind": "名詞辨識", "level": 1}, {"id": "v042", "topic": "英文名詞", "en": "What does “determinant” mean in linear algebra?", "zh": "線性代數中「determinant」的中文意思是什麼？", "options": ["行列式", "核空間", "維度", "正交矩陣"], "answer": [0], "explanation": "方陣的純量；det(AB)=det(A)det(B)，一般不能對加法拆開。", "kind": "名詞辨識", "level": 1}, {"id": "v043", "topic": "英文名詞", "en": "What does “cofactor” mean in linear algebra?", "zh": "線性代數中「cofactor」的中文意思是什麼？", "options": ["餘因子", "可逆", "特徵向量", "必要條件"], "answer": [0], "explanation": "Cᵢⱼ=(−1)ⁱ⁺ʲ 乘上刪除第 i row、第 j column 後的行列式。", "kind": "名詞辨識", "level": 1}, {"id": "v044", "topic": "英文名詞", "en": "What does “adjugate” mean in linear algebra?", "zh": "線性代數中「adjugate」的中文意思是什麼？", "options": ["正定", "古典伴隨矩陣", "充分條件", "自由變數"], "answer": [1], "explanation": "adj(A) 是 cofactor matrix 的轉置；A adj(A)=det(A)I。", "kind": "名詞辨識", "level": 1}, {"id": "v045", "topic": "英文名詞", "en": "What does “eigenvalue” mean in linear algebra?", "zh": "線性代數中「eigenvalue」的中文意思是什麼？", "options": ["像空間", "主元", "可逆", "特徵值"], "answer": [3], "explanation": "存在非零 v 使 Av=λv 的 λ；λ 可以是 0。", "kind": "名詞辨識", "level": 1}, {"id": "v046", "topic": "英文名詞", "en": "What does “eigenvector” mean in linear algebra?", "zh": "線性代數中「eigenvector」的中文意思是什麼？", "options": ["非奇異", "特徵向量", "奇異", "自由變數"], "answer": [1], "explanation": "滿足 Av=λv 的非零向量；零向量不是特徵向量。", "kind": "名詞辨識", "level": 1}, {"id": "v047", "topic": "英文名詞", "en": "What does “eigenspace” mean in linear algebra?", "zh": "線性代數中「eigenspace」的中文意思是什麼？", "options": ["非零", "零空間", "特徵空間", "列等價（橫向運算）"], "answer": [2], "explanation": "Eλ=N(A−λI)，包含零向量。", "kind": "名詞辨識", "level": 1}, {"id": "v048", "topic": "英文名詞", "en": "What does “algebraic multiplicity” mean in linear algebra?", "zh": "線性代數中「algebraic multiplicity」的中文意思是什麼？", "options": ["若且唯若／充要", "代數重數", "零度", "至多"], "answer": [1], "explanation": "λ 作為特徵多項式根的重數。", "kind": "名詞辨識", "level": 1}, {"id": "v049", "topic": "英文名詞", "en": "What does “geometric multiplicity” mean in linear algebra?", "zh": "線性代數中「geometric multiplicity」的中文意思是什麼？", "options": ["標準正交", "幾何重數", "代數重數", "唯一"], "answer": [1], "explanation": "dim N(A−λI)，即該特徵空間的維度。", "kind": "名詞辨識", "level": 1}, {"id": "v050", "topic": "英文名詞", "en": "What does “diagonalizable” mean in linear algebra?", "zh": "線性代數中「diagonalizable」的中文意思是什麼？", "options": ["可對角化", "定義域", "橫列空間", "有解／相容"], "answer": [0], "explanation": "存在可逆 P 使 P⁻¹AP 為對角矩陣，等價於有 n 個獨立特徵向量。", "kind": "名詞辨識", "level": 1}, {"id": "v051", "topic": "英文名詞", "en": "What does “similar” mean in linear algebra?", "zh": "線性代數中「similar」的中文意思是什麼？", "options": ["核空間", "相似", "滿射", "冪等"], "answer": [1], "explanation": "B=P⁻¹AP。代表同一線性算子在不同基底下的矩陣。", "kind": "名詞辨識", "level": 1}, {"id": "v052", "topic": "英文名詞", "en": "What does “characteristic polynomial” mean in linear algebra?", "zh": "線性代數中「characteristic polynomial」的中文意思是什麼？", "options": ["酉矩陣", "特徵多項式", "互異", "至少"], "answer": [1], "explanation": "此處採 det(tI−A)，根即特徵值。", "kind": "名詞辨識", "level": 1}, {"id": "v053", "topic": "英文名詞", "en": "What does “minimal polynomial” mean in linear algebra?", "zh": "線性代數中「minimal polynomial」的中文意思是什麼？", "options": ["維度", "正規方程式", "特徵多項式", "最小多項式"], "answer": [3], "explanation": "使 m(A)=0 的最低次首一多項式；整除特徵多項式。", "kind": "名詞辨識", "level": 1}, {"id": "v054", "topic": "英文名詞", "en": "What does “orthogonal” mean in linear algebra?", "zh": "線性代數中「orthogonal」的中文意思是什麼？", "options": ["正交", "互異", "核空間", "線性組合"], "answer": [0], "explanation": "向量內積為 0；非零正交向量必線性獨立。", "kind": "名詞辨識", "level": 1}, {"id": "v055", "topic": "英文名詞", "en": "What does “orthonormal” mean in linear algebra?", "zh": "線性代數中「orthonormal」的中文意思是什麼？", "options": ["定義域", "標準正交", "最簡列階梯形", "可對角化"], "answer": [1], "explanation": "互相正交且每個向量長度都為 1。", "kind": "名詞辨識", "level": 1}, {"id": "v056", "topic": "英文名詞", "en": "What does “orthogonal matrix” mean in linear algebra?", "zh": "線性代數中「orthogonal matrix」的中文意思是什麼？", "options": ["可對角化", "正交矩陣", "充分條件", "特徵多項式"], "answer": [1], "explanation": "實方陣 QᵀQ=I，因此 Q⁻¹=Qᵀ；保長度與內積。", "kind": "名詞辨識", "level": 1}, {"id": "v057", "topic": "英文名詞", "en": "What does “orthogonal complement” mean in linear algebra?", "zh": "線性代數中「orthogonal complement」的中文意思是什麼？", "options": ["正交補空間", "線性組合", "存在至少一個", "代數重數"], "answer": [0], "explanation": "W⊥ 為與 W 中每個向量都正交的所有向量。", "kind": "名詞辨識", "level": 1}, {"id": "v058", "topic": "英文名詞", "en": "What does “projection” mean in linear algebra?", "zh": "線性代數中「projection」的中文意思是什麼？", "options": ["投影", "最簡列階梯形", "無解／不相容", "雙射"], "answer": [0], "explanation": "一般投影算子 P 滿足 P²=P；正交投影另要求 Pᵀ=P（實數標準內積）。", "kind": "名詞辨識", "level": 1}, {"id": "v059", "topic": "英文名詞", "en": "What does “least squares” mean in linear algebra?", "zh": "線性代數中「least squares」的中文意思是什麼？", "options": ["必要條件", "主元", "最小平方法", "線性組合"], "answer": [2], "explanation": "最小化 ‖Ax−b‖²；實數情況滿足 normal equations AᵀAx=Aᵀb，複數情況改用共軛轉置 A*。", "kind": "名詞辨識", "level": 1}, {"id": "v060", "topic": "英文名詞", "en": "What does “normal equations” mean in linear algebra?", "zh": "線性代數中「normal equations」的中文意思是什麼？", "options": ["張成空間", "最簡列階梯形", "正規方程式", "線性組合"], "answer": [2], "explanation": "實數情況為 AᵀAx=Aᵀb；A 滿 column rank 時解唯一。複數情況將 Aᵀ 改為 A*。", "kind": "名詞辨識", "level": 1}, {"id": "v061", "topic": "英文名詞", "en": "What does “symmetric” mean in linear algebra?", "zh": "線性代數中「symmetric」的中文意思是什麼？", "options": ["自由變數", "對稱", "子空間之和", "子空間"], "answer": [1], "explanation": "實矩陣 Aᵀ=A，可正交對角化。", "kind": "名詞辨識", "level": 1}, {"id": "v062", "topic": "英文名詞", "en": "What does “Hermitian” mean in linear algebra?", "zh": "線性代數中「Hermitian」的中文意思是什麼？", "options": ["張成空間", "左零空間", "冪等", "厄米矩陣"], "answer": [3], "explanation": "複矩陣 A*=A，特徵值皆為實數。", "kind": "名詞辨識", "level": 1}, {"id": "v063", "topic": "英文名詞", "en": "What does “positive definite” mean in linear algebra?", "zh": "線性代數中「positive definite」的中文意思是什麼？", "options": ["線性組合", "可逆", "正定", "有解／相容"], "answer": [2], "explanation": "此處指實對稱 A，對所有非零 x，xᵀAx>0。", "kind": "名詞辨識", "level": 1}, {"id": "v064", "topic": "英文名詞", "en": "What does “positive semidefinite” mean in linear algebra?", "zh": "線性代數中「positive semidefinite」的中文意思是什麼？", "options": ["張成空間", "半正定", "轉置", "子空間之和"], "answer": [1], "explanation": "此處指實對稱 A，對所有 x，xᵀAx≥0；可以有零特徵值。", "kind": "名詞辨識", "level": 1}, {"id": "v065", "topic": "英文名詞", "en": "What does “idempotent” mean in linear algebra?", "zh": "線性代數中「idempotent」的中文意思是什麼？", "options": ["冪等", "最小平方法", "增廣矩陣", "雙射"], "answer": [0], "explanation": "A²=A；特徵值只能是 0 或 1。", "kind": "名詞辨識", "level": 1}, {"id": "v066", "topic": "英文名詞", "en": "What does “nilpotent” mean in linear algebra?", "zh": "線性代數中「nilpotent」的中文意思是什麼？", "options": ["冪零", "齊次方程組", "張成空間", "非奇異"], "answer": [0], "explanation": "存在正整數 k 使 Aᵏ=0；不表示 A 本身一定為 0。", "kind": "名詞辨識", "level": 1}, {"id": "v067", "topic": "英文名詞", "en": "What does “unitary” mean in linear algebra?", "zh": "線性代數中「unitary」的中文意思是什麼？", "options": ["酉矩陣", "特徵值", "半正定", "投影"], "answer": [0], "explanation": "複方陣 U*U=I，是正交矩陣的複數對應。", "kind": "名詞辨識", "level": 1}, {"id": "v068", "topic": "英文名詞", "en": "What does “singular value” mean in linear algebra?", "zh": "線性代數中「singular value」的中文意思是什麼？", "options": ["子空間之和", "線性獨立", "轉置", "奇異值"], "answer": [3], "explanation": "A*A 特徵值的非負平方根；與 A 的特徵值不同。", "kind": "名詞辨識", "level": 1}, {"id": "v069", "topic": "英文名詞", "en": "What does “necessary condition” mean in linear algebra?", "zh": "線性代數中「necessary condition」的中文意思是什麼？", "options": ["正交矩陣", "非奇異", "必要條件", "對稱"], "answer": [2], "explanation": "P 是 Q 的必要條件表示 Q⇒P；有 P 不保證 Q。", "kind": "名詞辨識", "level": 1}, {"id": "v070", "topic": "英文名詞", "en": "What does “sufficient condition” mean in linear algebra?", "zh": "線性代數中「sufficient condition」的中文意思是什麼？", "options": ["跡", "線性組合", "充分條件", "非零解"], "answer": [2], "explanation": "P 是 Q 的充分條件表示 P⇒Q。", "kind": "名詞辨識", "level": 1}, {"id": "v071", "topic": "英文名詞", "en": "What does “if and only if” mean in linear algebra?", "zh": "線性代數中「if and only if」的中文意思是什麼？", "options": ["奇異", "充分條件", "若且唯若／充要", "非奇異"], "answer": [2], "explanation": "P iff Q 表示兩個方向 P⇒Q 與 Q⇒P 都成立。", "kind": "名詞辨識", "level": 1}, {"id": "v072", "topic": "英文名詞", "en": "What does “at most” mean in linear algebra?", "zh": "線性代數中「at most」的中文意思是什麼？", "options": ["至多", "齊次方程組", "秩", "冪零"], "answer": [0], "explanation": "at most k 表示 ≤k，不是 ≥k。", "kind": "名詞辨識", "level": 1}, {"id": "v073", "topic": "英文名詞", "en": "What does “at least” mean in linear algebra?", "zh": "線性代數中「at least」的中文意思是什麼？", "options": ["零空間", "唯一", "至少", "冪等"], "answer": [2], "explanation": "at least k 表示 ≥k，不是 ≤k。", "kind": "名詞辨識", "level": 1}, {"id": "v074", "topic": "英文名詞", "en": "What does “distinct” mean in linear algebra?", "zh": "線性代數中「distinct」的中文意思是什麼？", "options": ["特徵多項式", "互異", "直和", "標準正交"], "answer": [1], "explanation": "distinct eigenvalues 表示不同數值的特徵值，不是計入重數後的個數。", "kind": "名詞辨識", "level": 1}, {"id": "v075", "topic": "英文名詞", "en": "What does “nonzero” mean in linear algebra?", "zh": "線性代數中「nonzero」的中文意思是什麼？", "options": ["正交補空間", "唯一", "非零", "核空間"], "answer": [2], "explanation": "非零向量只要求至少一個分量不為零。", "kind": "名詞辨識", "level": 1}, {"id": "v076", "topic": "英文名詞", "en": "What does “for every” mean in linear algebra?", "zh": "線性代數中「for every」的中文意思是什麼？", "options": ["對每一個", "特徵多項式", "古典伴隨矩陣", "增廣矩陣"], "answer": [0], "explanation": "全稱量詞；要推翻只需找到一個反例。", "kind": "名詞辨識", "level": 1}, {"id": "v077", "topic": "英文名詞", "en": "What does “there exists” mean in linear algebra?", "zh": "線性代數中「there exists」的中文意思是什麼？", "options": ["存在至少一個", "可逆", "相似", "定義域"], "answer": [0], "explanation": "存在量詞；要證明只需構造一個符合條件的例子。", "kind": "名詞辨識", "level": 1}, {"id": "v078", "topic": "英文名詞", "en": "What does “unique” mean in linear algebra?", "zh": "線性代數中「unique」的中文意思是什麼？", "options": ["特徵值", "雙射", "唯一", "有解／相容"], "answer": [2], "explanation": "恰有一個，包含存在性與不超過一個這兩件事。", "kind": "名詞辨識", "level": 1}, {"id": "pA00", "topic": "公式代入", "en": "A real 3 × 4 matrix A has rank 1. What is nullity(A)?", "zh": "A 是 3×4 實矩陣，rank(A)=1，求 nullity(A)。", "options": ["4", "3", "2", "33"], "answer": [1], "explanation": "有 4 個未知數。rank(A)+nullity(A)=4，所以零度=4−1=3。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB00", "topic": "公式代入", "en": "A real 3 × 4 matrix A has rank 1. Find dim N(Aᵀ).", "zh": "A 是 3×4 實矩陣，rank(A)=1，求左零空間維度。", "options": ["3", "4", "2", "33"], "answer": [2], "explanation": "Aᵀ 有 3 個 column，且 rank(Aᵀ)=1，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC00", "topic": "公式代入", "en": "Subspaces U and W have dimensions 3 and 2, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=3、dim W=2、dim(U∩W)=1，求和空間維度。", "options": ["6", "4", "5", "33"], "answer": [1], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=3+2−1=4。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD00", "topic": "公式代入", "en": "A is 2 × 2, det(A)=1. Find det(2A).", "zh": "A 為 2 階方陣，det(A)=1，求 det(2A)。", "options": ["5", "2", "4", "-4"], "answer": [2], "explanation": "每一個 row 都乘 2，共 2 個 row，因此 det(2A)=2^2 det(A)=4。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE00", "topic": "公式代入", "en": "Av=-5v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=-5v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["-2", "22", "28", "29"], "answer": [2], "explanation": "(A²+3I)v=((-5)²+3)v，所以特徵值為 28。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF00", "topic": "公式代入", "en": "A=diag(1, 2, 0). Find trace(A²).", "zh": "A=diag(1,2,0)，求 tr(A²)。", "options": ["9", "5", "3", "2"], "answer": [1], "explanation": "A²=diag(1,4,0)，跡為 5。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG00", "topic": "公式代入", "en": "T:ℝ^5→ℝ^3 is linear and dim ker(T)=3. Find dim R(T).", "zh": "T:ℝ^5→ℝ^3 線性，核空間維度 3，求像空間維度。", "options": ["3", "5", "6", "2"], "answer": [3], "explanation": "秩加零度等於定義域維度 5，所以 dim R(T)=5−3=2。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH00", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^4, with rank(P)=1. Find rank(I−P).", "zh": "ℝ^4 上的正交投影 P 之 rank 為 1。求 rank(I−P)。", "options": ["5", "6", "3", "4"], "answer": [2], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=4−1=3。P 的特徵值是 1 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA01", "topic": "公式代入", "en": "A real 4 × 5 matrix A has rank 2. What is nullity(A)?", "zh": "A 是 4×5 實矩陣，rank(A)=2，求 nullity(A)。", "options": ["5", "3", "33", "2"], "answer": [1], "explanation": "有 5 個未知數。rank(A)+nullity(A)=5，所以零度=5−2=3。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB01", "topic": "公式代入", "en": "A real 4 × 5 matrix A has rank 2. Find dim N(Aᵀ).", "zh": "A 是 4×5 實矩陣，rank(A)=2，求左零空間維度。", "options": ["2", "33", "4", "32"], "answer": [0], "explanation": "Aᵀ 有 4 個 column，且 rank(Aᵀ)=2，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC01", "topic": "公式代入", "en": "Subspaces U and W have dimensions 4 and 3, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=4、dim W=3、dim(U∩W)=2，求和空間維度。", "options": ["5", "6", "7", "9"], "answer": [0], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=4+3−2=5。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD01", "topic": "公式代入", "en": "A is 3 × 3, det(A)=2. Find det(3A).", "zh": "A 為 3 階方陣，det(A)=2，求 det(3A)。", "options": ["-54", "29", "54", "6"], "answer": [2], "explanation": "每一個 row 都乘 3，共 3 個 row，因此 det(3A)=3^3 det(A)=54。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE01", "topic": "公式代入", "en": "Av=-4v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=-4v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["13", "-1", "20", "19"], "answer": [3], "explanation": "(A²+3I)v=((-4)²+3)v，所以特徵值為 19。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF01", "topic": "公式代入", "en": "A=diag(2, 3, 0). Find trace(A²).", "zh": "A=diag(2,3,0)，求 tr(A²)。", "options": ["25", "5", "13", "6"], "answer": [2], "explanation": "A²=diag(4,9,0)，跡為 13。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG01", "topic": "公式代入", "en": "T:ℝ^6→ℝ^4 is linear and dim ker(T)=3. Find dim R(T).", "zh": "T:ℝ^6→ℝ^4 線性，核空間維度 3，求像空間維度。", "options": ["4", "6", "3", "7"], "answer": [2], "explanation": "秩加零度等於定義域維度 6，所以 dim R(T)=6−3=3。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH01", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^5, with rank(P)=2. Find rank(I−P).", "zh": "ℝ^5 上的正交投影 P 之 rank 為 2。求 rank(I−P)。", "options": ["3", "5", "8", "7"], "answer": [0], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=5−2=3。P 的特徵值是 2 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA02", "topic": "公式代入", "en": "A real 5 × 6 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 5×6 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["6", "4", "2", "3"], "answer": [3], "explanation": "有 6 個未知數。rank(A)+nullity(A)=6，所以零度=6−3=3。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB02", "topic": "公式代入", "en": "A real 5 × 6 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 5×6 實矩陣，rank(A)=3，求左零空間維度。", "options": ["4", "33", "5", "2"], "answer": [3], "explanation": "Aᵀ 有 5 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC02", "topic": "公式代入", "en": "Subspaces U and W have dimensions 5 and 4, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=5、dim W=4、dim(U∩W)=1，求和空間維度。", "options": ["9", "8", "10", "33"], "answer": [1], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=5+4−1=8。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD02", "topic": "公式代入", "en": "A is 4 × 4, det(A)=3. Find det(2A).", "zh": "A 為 4 階方陣，det(A)=3，求 det(2A)。", "options": ["-48", "48", "19", "6"], "answer": [1], "explanation": "每一個 row 都乘 2，共 4 個 row，因此 det(2A)=2^4 det(A)=48。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE02", "topic": "公式代入", "en": "Av=-3v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=-3v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["13", "0", "6", "12"], "answer": [3], "explanation": "(A²+3I)v=((-3)²+3)v，所以特徵值為 12。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF02", "topic": "公式代入", "en": "A=diag(3, 4, 0). Find trace(A²).", "zh": "A=diag(3,4,0)，求 tr(A²)。", "options": ["12", "7", "25", "49"], "answer": [2], "explanation": "A²=diag(9,16,0)，跡為 25。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG02", "topic": "公式代入", "en": "T:ℝ^7→ℝ^5 is linear and dim ker(T)=3. Find dim R(T).", "zh": "T:ℝ^7→ℝ^5 線性，核空間維度 3，求像空間維度。", "options": ["5", "7", "8", "4"], "answer": [3], "explanation": "秩加零度等於定義域維度 7，所以 dim R(T)=7−3=4。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH02", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^6, with rank(P)=3. Find rank(I−P).", "zh": "ℝ^6 上的正交投影 P 之 rank 為 3。求 rank(I−P)。", "options": ["6", "9", "10", "3"], "answer": [3], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=6−3=3。P 的特徵值是 3 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA03", "topic": "公式代入", "en": "A real 6 × 7 matrix A has rank 4. What is nullity(A)?", "zh": "A 是 6×7 實矩陣，rank(A)=4，求 nullity(A)。", "options": ["5", "7", "3", "2"], "answer": [2], "explanation": "有 7 個未知數。rank(A)+nullity(A)=7，所以零度=7−4=3。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB03", "topic": "公式代入", "en": "A real 6 × 7 matrix A has rank 4. Find dim N(Aᵀ).", "zh": "A 是 6×7 實矩陣，rank(A)=4，求左零空間維度。", "options": ["4", "33", "2", "6"], "answer": [2], "explanation": "Aᵀ 有 6 個 column，且 rank(Aᵀ)=4，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC03", "topic": "公式代入", "en": "Subspaces U and W have dimensions 6 and 5, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=6、dim W=5、dim(U∩W)=2，求和空間維度。", "options": ["9", "10", "11", "13"], "answer": [0], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=6+5−2=9。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD03", "topic": "公式代入", "en": "A is 5 × 5, det(A)=4. Find det(3A).", "zh": "A 為 5 階方陣，det(A)=4，求 det(3A)。", "options": ["-972", "247", "12", "972"], "answer": [3], "explanation": "每一個 row 都乘 3，共 5 個 row，因此 det(3A)=3^5 det(A)=972。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE03", "topic": "公式代入", "en": "Av=-2v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=-2v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["33", "1", "7", "8"], "answer": [2], "explanation": "(A²+3I)v=((-2)²+3)v，所以特徵值為 7。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF03", "topic": "公式代入", "en": "A=diag(4, 5, 0). Find trace(A²).", "zh": "A=diag(4,5,0)，求 tr(A²)。", "options": ["81", "9", "41", "20"], "answer": [2], "explanation": "A²=diag(16,25,0)，跡為 41。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG03", "topic": "公式代入", "en": "T:ℝ^8→ℝ^3 is linear and dim ker(T)=6. Find dim R(T).", "zh": "T:ℝ^8→ℝ^3 線性，核空間維度 6，求像空間維度。", "options": ["9", "8", "3", "2"], "answer": [3], "explanation": "秩加零度等於定義域維度 8，所以 dim R(T)=8−6=2。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH03", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^7, with rank(P)=1. Find rank(I−P).", "zh": "ℝ^7 上的正交投影 P 之 rank 為 1。求 rank(I−P)。", "options": ["7", "6", "8", "9"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=7−1=6。P 的特徵值是 1 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA04", "topic": "公式代入", "en": "A real 7 × 8 matrix A has rank 5. What is nullity(A)?", "zh": "A 是 7×8 實矩陣，rank(A)=5，求 nullity(A)。", "options": ["6", "8", "3", "2"], "answer": [2], "explanation": "有 8 個未知數。rank(A)+nullity(A)=8，所以零度=8−5=3。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB04", "topic": "公式代入", "en": "A real 7 × 8 matrix A has rank 5. Find dim N(Aᵀ).", "zh": "A 是 7×8 實矩陣，rank(A)=5，求左零空間維度。", "options": ["33", "4", "7", "2"], "answer": [3], "explanation": "Aᵀ 有 7 個 column，且 rank(Aᵀ)=5，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC04", "topic": "公式代入", "en": "Subspaces U and W have dimensions 7 and 2, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=7、dim W=2、dim(U∩W)=1，求和空間維度。", "options": ["10", "8", "33", "9"], "answer": [1], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=7+2−1=8。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD04", "topic": "公式代入", "en": "A is 2 × 2, det(A)=5. Find det(2A).", "zh": "A 為 2 階方陣，det(A)=5，求 det(2A)。", "options": ["9", "20", "-20", "10"], "answer": [1], "explanation": "每一個 row 都乘 2，共 2 個 row，因此 det(2A)=2^2 det(A)=20。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE04", "topic": "公式代入", "en": "Av=-1v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=-1v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["-2", "4", "5", "2"], "answer": [1], "explanation": "(A²+3I)v=((-1)²+3)v，所以特徵值為 4。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF04", "topic": "公式代入", "en": "A=diag(5, 6, 0). Find trace(A²).", "zh": "A=diag(5,6,0)，求 tr(A²)。", "options": ["121", "30", "11", "61"], "answer": [3], "explanation": "A²=diag(25,36,0)，跡為 61。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG04", "topic": "公式代入", "en": "T:ℝ^9→ℝ^4 is linear and dim ker(T)=6. Find dim R(T).", "zh": "T:ℝ^9→ℝ^4 線性，核空間維度 6，求像空間維度。", "options": ["9", "3", "10", "4"], "answer": [1], "explanation": "秩加零度等於定義域維度 9，所以 dim R(T)=9−6=3。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH04", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^8, with rank(P)=2. Find rank(I−P).", "zh": "ℝ^8 上的正交投影 P 之 rank 為 2。求 rank(I−P)。", "options": ["8", "6", "11", "10"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=8−2=6。P 的特徵值是 2 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA05", "topic": "公式代入", "en": "A real 3 × 9 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 3×9 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["4", "6", "9", "0"], "answer": [1], "explanation": "有 9 個未知數。rank(A)+nullity(A)=9，所以零度=9−3=6。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB05", "topic": "公式代入", "en": "A real 3 × 9 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 3×9 實矩陣，rank(A)=3，求左零空間維度。", "options": ["3", "5", "7", "0"], "answer": [3], "explanation": "Aᵀ 有 3 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=0。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC05", "topic": "公式代入", "en": "Subspaces U and W have dimensions 8 and 3, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=8、dim W=3、dim(U∩W)=2，求和空間維度。", "options": ["9", "11", "10", "13"], "answer": [0], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=8+3−2=9。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD05", "topic": "公式代入", "en": "A is 3 × 3, det(A)=6. Find det(3A).", "zh": "A 為 3 階方陣，det(A)=6，求 det(3A)。", "options": ["162", "18", "-162", "33"], "answer": [0], "explanation": "每一個 row 都乘 3，共 3 個 row，因此 det(3A)=3^3 det(A)=162。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE05", "topic": "公式代入", "en": "Av=0v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=0v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["4", "-3", "33", "3"], "answer": [3], "explanation": "(A²+3I)v=((0)²+3)v，所以特徵值為 3。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF05", "topic": "公式代入", "en": "A=diag(6, 7, 0). Find trace(A²).", "zh": "A=diag(6,7,0)，求 tr(A²)。", "options": ["85", "42", "13", "169"], "answer": [0], "explanation": "A²=diag(36,49,0)，跡為 85。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG05", "topic": "公式代入", "en": "T:ℝ^10→ℝ^5 is linear and dim ker(T)=6. Find dim R(T).", "zh": "T:ℝ^10→ℝ^5 線性，核空間維度 6，求像空間維度。", "options": ["5", "11", "10", "4"], "answer": [3], "explanation": "秩加零度等於定義域維度 10，所以 dim R(T)=10−6=4。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH05", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^9, with rank(P)=3. Find rank(I−P).", "zh": "ℝ^9 上的正交投影 P 之 rank 為 3。求 rank(I−P)。", "options": ["13", "12", "6", "9"], "answer": [2], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=9−3=6。P 的特徵值是 3 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA06", "topic": "公式代入", "en": "A real 4 × 10 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 4×10 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["7", "10", "1", "4"], "answer": [0], "explanation": "有 10 個未知數。rank(A)+nullity(A)=10，所以零度=10−3=7。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB06", "topic": "公式代入", "en": "A real 4 × 10 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 4×10 實矩陣，rank(A)=3，求左零空間維度。", "options": ["8", "5", "1", "4"], "answer": [2], "explanation": "Aᵀ 有 4 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=1。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC06", "topic": "公式代入", "en": "Subspaces U and W have dimensions 9 and 4, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=9、dim W=4、dim(U∩W)=1，求和空間維度。", "options": ["33", "13", "12", "14"], "answer": [2], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=9+4−1=12。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD06", "topic": "公式代入", "en": "A is 4 × 4, det(A)=7. Find det(2A).", "zh": "A 為 4 階方陣，det(A)=7，求 det(2A)。", "options": ["-112", "23", "112", "14"], "answer": [2], "explanation": "每一個 row 都乘 2，共 4 個 row，因此 det(2A)=2^4 det(A)=112。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE06", "topic": "公式代入", "en": "Av=1v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=1v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["33", "4", "5", "-2"], "answer": [1], "explanation": "(A²+3I)v=((1)²+3)v，所以特徵值為 4。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF06", "topic": "公式代入", "en": "A=diag(7, 8, 0). Find trace(A²).", "zh": "A=diag(7,8,0)，求 tr(A²)。", "options": ["113", "225", "15", "56"], "answer": [0], "explanation": "A²=diag(49,64,0)，跡為 113。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG06", "topic": "公式代入", "en": "T:ℝ^11→ℝ^3 is linear and dim ker(T)=9. Find dim R(T).", "zh": "T:ℝ^11→ℝ^3 線性，核空間維度 9，求像空間維度。", "options": ["12", "3", "2", "11"], "answer": [2], "explanation": "秩加零度等於定義域維度 11，所以 dim R(T)=11−9=2。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH06", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^10, with rank(P)=1. Find rank(I−P).", "zh": "ℝ^10 上的正交投影 P 之 rank 為 1。求 rank(I−P)。", "options": ["10", "9", "12", "11"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=10−1=9。P 的特徵值是 1 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA07", "topic": "公式代入", "en": "A real 5 × 11 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 5×11 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["8", "4", "11", "2"], "answer": [0], "explanation": "有 11 個未知數。rank(A)+nullity(A)=11，所以零度=11−3=8。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB07", "topic": "公式代入", "en": "A real 5 × 11 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 5×11 實矩陣，rank(A)=3，求左零空間維度。", "options": ["33", "9", "2", "5"], "answer": [2], "explanation": "Aᵀ 有 5 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=2。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC07", "topic": "公式代入", "en": "Subspaces U and W have dimensions 10 and 5, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=10、dim W=5、dim(U∩W)=2，求和空間維度。", "options": ["17", "14", "15", "13"], "answer": [3], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=10+5−2=13。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD07", "topic": "公式代入", "en": "A is 5 × 5, det(A)=8. Find det(3A).", "zh": "A 為 5 階方陣，det(A)=8，求 det(3A)。", "options": ["1944", "24", "251", "-1944"], "answer": [0], "explanation": "每一個 row 都乘 3，共 5 個 row，因此 det(3A)=3^5 det(A)=1944。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE07", "topic": "公式代入", "en": "Av=2v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=2v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["5", "8", "1", "7"], "answer": [3], "explanation": "(A²+3I)v=((2)²+3)v，所以特徵值為 7。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF07", "topic": "公式代入", "en": "A=diag(8, 9, 0). Find trace(A²).", "zh": "A=diag(8,9,0)，求 tr(A²)。", "options": ["289", "145", "17", "72"], "answer": [1], "explanation": "A²=diag(64,81,0)，跡為 145。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG07", "topic": "公式代入", "en": "T:ℝ^12→ℝ^4 is linear and dim ker(T)=9. Find dim R(T).", "zh": "T:ℝ^12→ℝ^4 線性，核空間維度 9，求像空間維度。", "options": ["13", "4", "12", "3"], "answer": [3], "explanation": "秩加零度等於定義域維度 12，所以 dim R(T)=12−9=3。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH07", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^11, with rank(P)=2. Find rank(I−P).", "zh": "ℝ^11 上的正交投影 P 之 rank 為 2。求 rank(I−P)。", "options": ["13", "14", "11", "9"], "answer": [3], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=11−2=9。P 的特徵值是 2 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA08", "topic": "公式代入", "en": "A real 6 × 12 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 6×12 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["3", "4", "12", "9"], "answer": [3], "explanation": "有 12 個未知數。rank(A)+nullity(A)=12，所以零度=12−3=9。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB08", "topic": "公式代入", "en": "A real 6 × 12 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 6×12 實矩陣，rank(A)=3，求左零空間維度。", "options": ["6", "5", "3", "10"], "answer": [2], "explanation": "Aᵀ 有 6 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=3。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC08", "topic": "公式代入", "en": "Subspaces U and W have dimensions 11 and 2, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=11、dim W=2、dim(U∩W)=1，求和空間維度。", "options": ["14", "12", "13", "33"], "answer": [1], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=11+2−1=12。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD08", "topic": "公式代入", "en": "A is 2 × 2, det(A)=9. Find det(2A).", "zh": "A 為 2 階方陣，det(A)=9，求 det(2A)。", "options": ["18", "36", "-36", "13"], "answer": [1], "explanation": "每一個 row 都乘 2，共 2 個 row，因此 det(2A)=2^2 det(A)=36。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE08", "topic": "公式代入", "en": "Av=3v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=3v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["6", "33", "12", "13"], "answer": [2], "explanation": "(A²+3I)v=((3)²+3)v，所以特徵值為 12。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF08", "topic": "公式代入", "en": "A=diag(9, 10, 0). Find trace(A²).", "zh": "A=diag(9,10,0)，求 tr(A²)。", "options": ["181", "19", "90", "361"], "answer": [0], "explanation": "A²=diag(81,100,0)，跡為 181。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG08", "topic": "公式代入", "en": "T:ℝ^13→ℝ^5 is linear and dim ker(T)=9. Find dim R(T).", "zh": "T:ℝ^13→ℝ^5 線性，核空間維度 9，求像空間維度。", "options": ["13", "5", "4", "14"], "answer": [2], "explanation": "秩加零度等於定義域維度 13，所以 dim R(T)=13−9=4。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH08", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^12, with rank(P)=3. Find rank(I−P).", "zh": "ℝ^12 上的正交投影 P 之 rank 為 3。求 rank(I−P)。", "options": ["16", "9", "12", "15"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=12−3=9。P 的特徵值是 3 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA09", "topic": "公式代入", "en": "A real 7 × 13 matrix A has rank 3. What is nullity(A)?", "zh": "A 是 7×13 實矩陣，rank(A)=3，求 nullity(A)。", "options": ["13", "33", "4", "10"], "answer": [3], "explanation": "有 13 個未知數。rank(A)+nullity(A)=13，所以零度=13−3=10。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB09", "topic": "公式代入", "en": "A real 7 × 13 matrix A has rank 3. Find dim N(Aᵀ).", "zh": "A 是 7×13 實矩陣，rank(A)=3，求左零空間維度。", "options": ["5", "11", "4", "7"], "answer": [2], "explanation": "Aᵀ 有 7 個 column，且 rank(Aᵀ)=3，所以 dim N(Aᵀ)=4。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC09", "topic": "公式代入", "en": "Subspaces U and W have dimensions 12 and 3, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=12、dim W=3、dim(U∩W)=2，求和空間維度。", "options": ["14", "15", "13", "17"], "answer": [2], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=12+3−2=13。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD09", "topic": "公式代入", "en": "A is 3 × 3, det(A)=10. Find det(3A).", "zh": "A 為 3 階方陣，det(A)=10，求 det(3A)。", "options": ["270", "-270", "37", "30"], "answer": [0], "explanation": "每一個 row 都乘 3，共 3 個 row，因此 det(3A)=3^3 det(A)=270。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE09", "topic": "公式代入", "en": "Av=4v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=4v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["7", "13", "20", "19"], "answer": [3], "explanation": "(A²+3I)v=((4)²+3)v，所以特徵值為 19。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF09", "topic": "公式代入", "en": "A=diag(10, 11, 0). Find trace(A²).", "zh": "A=diag(10,11,0)，求 tr(A²)。", "options": ["110", "441", "21", "221"], "answer": [3], "explanation": "A²=diag(100,121,0)，跡為 221。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG09", "topic": "公式代入", "en": "T:ℝ^14→ℝ^3 is linear and dim ker(T)=12. Find dim R(T).", "zh": "T:ℝ^14→ℝ^3 線性，核空間維度 12，求像空間維度。", "options": ["2", "14", "15", "3"], "answer": [0], "explanation": "秩加零度等於定義域維度 14，所以 dim R(T)=14−12=2。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH09", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^13, with rank(P)=1. Find rank(I−P).", "zh": "ℝ^13 上的正交投影 P 之 rank 為 1。求 rank(I−P)。", "options": ["13", "12", "15", "14"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=13−1=12。P 的特徵值是 1 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA10", "topic": "公式代入", "en": "A real 3 × 14 matrix A has rank 2. What is nullity(A)?", "zh": "A 是 3×14 實矩陣，rank(A)=2，求 nullity(A)。", "options": ["12", "14", "1", "3"], "answer": [0], "explanation": "有 14 個未知數。rank(A)+nullity(A)=14，所以零度=14−2=12。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB10", "topic": "公式代入", "en": "A real 3 × 14 matrix A has rank 2. Find dim N(Aᵀ).", "zh": "A 是 3×14 實矩陣，rank(A)=2，求左零空間維度。", "options": ["13", "1", "3", "4"], "answer": [1], "explanation": "Aᵀ 有 3 個 column，且 rank(Aᵀ)=2，所以 dim N(Aᵀ)=1。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC10", "topic": "公式代入", "en": "Subspaces U and W have dimensions 13 and 4, with dim(U ∩ W)=1. Find dim(U+W).", "zh": "dim U=13、dim W=4、dim(U∩W)=1，求和空間維度。", "options": ["18", "17", "16", "33"], "answer": [2], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=13+4−1=16。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD10", "topic": "公式代入", "en": "A is 4 × 4, det(A)=11. Find det(2A).", "zh": "A 為 4 階方陣，det(A)=11，求 det(2A)。", "options": ["27", "176", "22", "-176"], "answer": [1], "explanation": "每一個 row 都乘 2，共 4 個 row，因此 det(2A)=2^4 det(A)=176。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE10", "topic": "公式代入", "en": "Av=5v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=5v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["22", "29", "28", "8"], "answer": [2], "explanation": "(A²+3I)v=((5)²+3)v，所以特徵值為 28。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF10", "topic": "公式代入", "en": "A=diag(11, 12, 0). Find trace(A²).", "zh": "A=diag(11,12,0)，求 tr(A²)。", "options": ["132", "265", "529", "23"], "answer": [1], "explanation": "A²=diag(121,144,0)，跡為 265。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG10", "topic": "公式代入", "en": "T:ℝ^15→ℝ^4 is linear and dim ker(T)=12. Find dim R(T).", "zh": "T:ℝ^15→ℝ^4 線性，核空間維度 12，求像空間維度。", "options": ["15", "4", "3", "16"], "answer": [2], "explanation": "秩加零度等於定義域維度 15，所以 dim R(T)=15−12=3。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH10", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^14, with rank(P)=2. Find rank(I−P).", "zh": "ℝ^14 上的正交投影 P 之 rank 為 2。求 rank(I−P)。", "options": ["17", "12", "14", "16"], "answer": [1], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=14−2=12。P 的特徵值是 2 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "pA11", "topic": "公式代入", "en": "A real 4 × 15 matrix A has rank 4. What is nullity(A)?", "zh": "A 是 4×15 實矩陣，rank(A)=4，求 nullity(A)。", "options": ["11", "0", "15", "5"], "answer": [0], "explanation": "有 15 個未知數。rank(A)+nullity(A)=15，所以零度=15−4=11。這是自由變數數目。", "kind": "公式變式", "level": 1, "family": "A"}, {"id": "pB11", "topic": "公式代入", "en": "A real 4 × 15 matrix A has rank 4. Find dim N(Aᵀ).", "zh": "A 是 4×15 實矩陣，rank(A)=4，求左零空間維度。", "options": ["12", "4", "6", "0"], "answer": [3], "explanation": "Aᵀ 有 4 個 column，且 rank(Aᵀ)=4，所以 dim N(Aᵀ)=0。注意不是用原矩陣的 column 數。", "kind": "公式變式", "level": 1, "family": "B"}, {"id": "pC11", "topic": "公式代入", "en": "Subspaces U and W have dimensions 14 and 5, with dim(U ∩ W)=2. Find dim(U+W).", "zh": "dim U=14、dim W=5、dim(U∩W)=2，求和空間維度。", "options": ["18", "17", "21", "19"], "answer": [1], "explanation": "dim(U+W)=dim U+dim W−dim(U∩W)=14+5−2=17。交集重複算了一次，要扣掉。", "kind": "公式變式", "level": 1, "family": "C"}, {"id": "pD11", "topic": "公式代入", "en": "A is 5 × 5, det(A)=12. Find det(3A).", "zh": "A 為 5 階方陣，det(A)=12，求 det(3A)。", "options": ["2916", "255", "-2916", "36"], "answer": [0], "explanation": "每一個 row 都乘 3，共 5 個 row，因此 det(3A)=3^5 det(A)=2916。", "kind": "公式變式", "level": 1, "family": "D"}, {"id": "pE11", "topic": "公式代入", "en": "Av=6v with v≠0. What is the eigenvalue of A²+3I associated with v?", "zh": "Av=6v 且 v≠0。v 對應於 A²+3I 的特徵值是？", "options": ["39", "9", "33", "40"], "answer": [0], "explanation": "(A²+3I)v=((6)²+3)v，所以特徵值為 39。先將特徵值平方，再加 3；負數平方務必保留括號。原特徵向量可繼續使用。", "kind": "公式變式", "level": 1, "family": "E"}, {"id": "pF11", "topic": "公式代入", "en": "A=diag(12, 13, 0). Find trace(A²).", "zh": "A=diag(12,13,0)，求 tr(A²)。", "options": ["25", "313", "156", "625"], "answer": [1], "explanation": "A²=diag(144,169,0)，跡為 313。tr(A²) 一般不等於 (tr A)²。", "kind": "公式變式", "level": 1, "family": "F"}, {"id": "pG11", "topic": "公式代入", "en": "T:ℝ^16→ℝ^5 is linear and dim ker(T)=12. Find dim R(T).", "zh": "T:ℝ^16→ℝ^5 線性，核空間維度 12，求像空間維度。", "options": ["16", "4", "17", "5"], "answer": [1], "explanation": "秩加零度等於定義域維度 16，所以 dim R(T)=16−12=4。不能直接拿陪域維度當 rank。", "kind": "公式變式", "level": 1, "family": "G"}, {"id": "pH11", "topic": "公式代入", "en": "P is an orthogonal projection on ℝ^15, with rank(P)=3. Find rank(I−P).", "zh": "ℝ^15 上的正交投影 P 之 rank 為 3。求 rank(I−P)。", "options": ["12", "18", "15", "19"], "answer": [0], "explanation": "I−P 投影到P 的像空間 R(P) 的正交補，維度=15−3=12。P 的特徵值是 3 個 1 與其餘 0。", "kind": "公式變式", "level": 1, "family": "H"}, {"id": "e001", "topic": "矩陣與運算", "en": "A real 7×7 matrix K satisfies Kᵀ = −K. What follows?", "zh": "實數7×7矩陣K滿足Kᵀ=−K，哪些結論成立？", "options": ["det(K)=0", "K is invertible（可逆）", "rank(K)≤6", "Every diagonal entry is zero（對角元素全零）"], "answer": [0, 2, 3], "explanation": "反對稱是Kᵀ=−K。行列式滿足det(K)=det(Kᵀ)=det(−K)=(−1)⁷det(K)，故det(K)=0，所以不可逆且rank≤6。對角元素滿足kᵢᵢ=−kᵢᵢ，故為0。注意奇數階是推出奇異的關鍵。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第1頁第1題：矩陣性質"}, "multiple": true}, {"id": "e002", "topic": "線性轉換", "en": "Define T(x,y)=(y,0) on ℝ². Choose the valid descriptions.", "zh": "T(x,y)=(y,0)，判斷核與值域。", "options": ["N(T)=span{(1,0)}", "R(T)=span{(1,0)}", "N(T)∩R(T)={0}", "T² is the zero map（零轉換）"], "answer": [0, 1, 3], "explanation": "核看哪些輸入變成零：(y,0)=(0,0)要求y=0，所以核是x軸。輸出也永遠在x軸，所以值域是x軸。兩者交集是整條x軸，並非只有零。再做一次T，得到T(y,0)=(0,0)。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第1頁第1題：值域與核"}, "multiple": true}, {"id": "e003", "topic": "向量空間與基底", "en": "Which sets inside ℝ² are vector subspaces?", "zh": "下列哪些集合是ℝ²的子空間？", "options": ["{(x,y):x−2y=0}", "{(x,y):x−2y=3}", "{(x,y):xy=0}", "span{(2,1),(4,2)}"], "answer": [0, 3], "explanation": "齊次線性條件x−2y=0可寫成t(2,1)，對加法及數乘封閉。常數3的集合不包含零。xy=0是兩座標軸的聯集；(1,0)+(0,1)=(1,1)不在內。任何span都是子空間，生成向量相依也不影響。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第1頁第2題：子空間"}, "multiple": true}, {"id": "e004", "topic": "秩與四大空間", "en": "A 3×5 matrix A has three pivots. Consider T(x)=Ax from ℝ⁵ to ℝ³.", "zh": "3×5矩陣A有3個樞紐，T:ℝ⁵→ℝ³，哪些敘述成立？", "options": ["T is onto（滿射）", "T is one-to-one（單射）", "dim N(T)=2", "dim R(T)=3"], "answer": [0, 2, 3], "explanation": "rank=3等於輸出空間維度，所以滿射。rank-nullity用輸入維度5：nullity=5−3=2。核不是{0}，所以不單射。滿射與單射要分開看，長方形矩陣可以只具其中一個。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第1頁第3題：矩陣轉換"}, "multiple": true}, {"id": "e005", "topic": "秩與四大空間", "en": "Let A:ℝ⁴→ℝ³ and B:ℝ²→ℝ⁴ be matrix maps. Select what must hold.", "zh": "A為3×4、B為4×2，哪些必定成立？", "options": ["R(AB)⊆R(A)", "rank(AB)≤rank(A)", "R(A)⊆R(AB)", "rank(AB)≤2"], "answer": [0, 1, 3], "explanation": "ABx=A(Bx)，因此AB的每個輸出都已是A可產生的輸出。子空間包含導致維度不等式rank(AB)≤rank(A)。AB只有2欄，rank也不超過2。取B=0而A≠0，就知道反向包含不一定成立。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第2頁第4題：乘積的列空間"}, "multiple": true}, {"id": "e006", "topic": "聯立方程與消去", "en": "A is an invertible 4×4 matrix. Evaluate these statements about row reduction.", "zh": "A是可逆4×4矩陣，判斷列簡化的性質。", "options": ["rref(A)=I₄", "rref(A) is unique（唯一）", "det(A) must equal 1", "Elementary row operations preserve rank（秩不變）"], "answer": [0, 1, 3], "explanation": "可逆表示每欄都有pivot，簡化列階梯形只能是單位矩陣；RREF對任何矩陣都唯一。列運算保留rank，但交換列會改行列式符號，倍乘列會改行列式倍數。例A=2I₄的det是16，不是1。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第2頁第5題：RREF"}, "multiple": true}, {"id": "e007", "topic": "內積與正交", "en": "A is real symmetric. Nonzero vectors u and v are eigenvectors. When is orthogonality guaranteed?", "zh": "A為實對稱矩陣，非零u、v都是特徵向量。何種條件保證互相正交？", "options": ["Their eigenvalues are different（特徵值相異）", "They are merely linearly independent（僅線性獨立）", "They have equal lengths（等長）", "They share one eigenvalue（特徵值相同）"], "answer": [0], "explanation": "Au=λu、Av=μv。對稱性給uᵀAv=(Au)ᵀv，因此(μ−λ)uᵀv=0。λ≠μ時才能必然推出內積0。同一特徵空間中的向量可以不正交；取A=I、u=(1,0)、v=(1,1)即反例。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 112 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/112/2023-338.pdf", "locator": "原卷第2頁第6題：特徵向量正交"}, "multiple": true}, {"id": "e008", "topic": "向量空間與基底", "en": "Let H={(a+2b,3a+6b,c):a,b,c∈ℝ}. Find dim H.", "zh": "H={(a+2b,3a+6b,c):a,b,c為實數}，求維度。", "options": ["1", "2", "3", "The parameter count always equals the dimension（參數個數就是維度）"], "answer": [1], "explanation": "寫成a(1,3,0)+b(2,6,0)+c(0,0,1)。第二向量是第一的2倍，只有(1,3,0)、(0,0,1)提供獨立方向，故維度2。參數可重複描述同一方向，不能直接數參數。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第1頁第1題：參數式子空間維度"}, "multiple": true}, {"id": "e009", "topic": "內積與正交", "en": "Project b=(2,0,3) orthogonally onto W=span{(1,1,0),(0,0,1)}.", "zh": "將b=(2,0,3)正交投影到W=span{(1,1,0),(0,0,1)}。", "options": ["(1,1,3)", "(2,2,3)", "(1,−1,0)", "(0,0,3)"], "answer": [0], "explanation": "兩生成向量互相正交，可以分別投影後相加。沿u=(1,1,0)的係數是(b·u)/(u·u)=2/2=1；沿v=(0,0,1)係數是3。結果(1,1,3)。殘差b−p=(1,−1,0)與W正交，但殘差不是投影。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第1頁第2題：正交投影"}, "multiple": true}, {"id": "e010", "topic": "線性轉換", "en": "On P₂, T(a+bt+ct²)=2a+(a+3b)t+ct². Which matrix represents T in (1,t,t²)?", "zh": "以基底(1,t,t²)，T(a+bt+ct²)=2a+(a+3b)t+ct²的矩陣為何？", "options": ["[[2,0,0],[1,3,0],[0,0,1]]", "[[2,1,0],[0,3,0],[0,0,1]]", "[[1,0,0],[0,2,0],[0,0,3]]"], "answer": [0], "explanation": "矩陣每一欄放一個基底向量的輸出座標。T(1)=2+t給第一欄(2,1,0)；T(t)=3t給第二欄(0,3,0)；T(t²)=t²給第三欄(0,0,1)。不要把各輸出座標橫著排。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第1頁第3題：矩陣表示"}, "multiple": true}, {"id": "e011", "topic": "座標與相似", "en": "Let B=[b₁ b₂] and C=[c₁ c₂] be invertible basis matrices. Which converts B-coordinates to C-coordinates?", "zh": "B、C的欄是兩組基底；把[v]B變成[v]C的矩陣是哪個？", "options": ["C⁻¹B", "B⁻¹C", "BC⁻¹", "CB⁻¹"], "answer": [0], "explanation": "先用B把B座標還原為向量v=B[v]B，再用C⁻¹把v換成C座標。因此[v]C=C⁻¹B[v]B。讀from B to C時，要確認輸入是哪一套座標；轉換的逆矩陣B⁻¹C方向相反。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第2頁第4題：換基"}, "multiple": true}, {"id": "e012", "topic": "對稱矩陣與正定", "en": "For Q(x,y)=4x²+6xy+2y², find the symmetric matrix M with Q=zᵀMz.", "zh": "Q(x,y)=4x²+6xy+2y²，對稱矩陣M使Q=zᵀMz，M是哪個？", "options": ["[[4,3],[3,2]]", "[[4,6],[6,2]]", "[[4,0],[0,2]]"], "answer": [0], "explanation": "展開zᵀMz=m₁₁x²+(m₁₂+m₂₁)xy+m₂₂y²。對稱要求m₁₂=m₂₁，所以交叉項6要分給兩格，各填3。若兩格都填6，展開後會變12xy。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第2頁第6題：二次型"}, "multiple": true}, {"id": "e013", "topic": "秩與四大空間", "en": "A 5×8 matrix has four nonzero rows in an echelon form. What is its nullity?", "zh": "5×8矩陣的階梯形有4個非零列，nullity為何？", "options": ["1", "3", "4", "5"], "answer": [2], "explanation": "階梯形每個非零列提供一個pivot，所以rank=4。nullity是自由變數數目；8個未知數扣4個pivot，得到4。rank+nullity=欄數8，不是列數5。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第3頁第7題：nullity"}, "multiple": true}, {"id": "e014", "topic": "最小平方與投影", "en": "A is real and has independent columns. Which formula gives the unique least-squares solution for Ax≈b?", "zh": "A為實矩陣且欄向量獨立，Ax≈b唯一最小平方解為何？", "options": ["(AᵀA)⁻¹Aᵀb", "Aᵀb for every A（永遠只要Aᵀb）", "(AAᵀ)⁻¹b", "A⁻¹b even when A is rectangular（長方形也可直接取逆）"], "answer": [0], "explanation": "最小平方讓殘差b−Ax垂直於Col(A)，故Aᵀ(b−Ax)=0，整理成AᵀAx=Aᵀb。欄獨立保證AᵀA可逆。只有A的欄標準正交、使AᵀA=I時，才可簡化為Aᵀb。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 113 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/113/113-307.pdf", "locator": "原卷第3頁第9題：最小平方"}, "multiple": true}, {"id": "e015", "topic": "聯立方程與消去", "en": "A is real 2×3 with rank 2. How many solutions does Ax=b have for any b∈ℝ²?", "zh": "實數2×3矩陣A的rank為2，任意b∈ℝ²時Ax=b有幾個解？", "options": ["Exactly one（唯一）", "Infinitely many（無限多）", "None（無解）", "It depends on b（隨b改變）"], "answer": [1], "explanation": "rank=列數2，故A滿射，所有b都有解。nullity=3−2=1，存在非零齊次解；找到特解xₚ後，xₚ+tv全都是解，所以無限多。不是所有非方陣都無解。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第16題：方程組解的型態"}, "multiple": true}, {"id": "e016", "topic": "矩陣與運算", "en": "A is 2×5 and B is 5×3. Select correct formulas and sizes.", "zh": "A為2×5、B為5×3，判斷公式與尺寸。", "options": ["(AB)ᵀ=BᵀAᵀ", "AB is 2×3", "AᵀBᵀ is defined（乘法有定義）", "(AB)ᵀ is 3×2"], "answer": [0, 1, 3], "explanation": "AB內側尺寸5相同，結果2×3。轉置後3×2，且乘積轉置需倒序。BᵀAᵀ=(3×5)(5×2)可乘。AᵀBᵀ=(5×2)(3×5)內側2與3不同，根本不能乘。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第17題：轉置乘積"}, "multiple": true}, {"id": "e017", "topic": "行列式與可逆", "en": "A is 3×3 and det(A)=−2. Compute det(−2A).", "zh": "A為3×3且det(A)=−2，求det(−2A)。", "options": ["4", "−16", "16", "−4"], "answer": [2], "explanation": "整個矩陣乘−2等於三列各乘−2，行列式共乘(−2)³。因此det(−2A)=(−8)(−2)=16。公式是det(kA)=kⁿdet(A)，不是只乘一次k。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第18題：行列式縮放"}, "multiple": true}, {"id": "e018", "topic": "秩與四大空間", "en": "For A=[[1,2],[0,0]], compare its row and column spaces.", "zh": "A=[[1,2],[0,0]]，比較Row(A)與Col(A)。", "options": ["Both dimensions are 1（維度都為1）", "The spaces are equal（兩空間相等）", "Row(A)=span{(1,2)}", "Col(A)=span{(1,0)}"], "answer": [0, 2, 3], "explanation": "非零橫列只有(1,2)，所以row space是其span。直欄為(1,0)、(2,0)，所以column space是x軸。兩空間維度同為rank=1，但方向不同。相同維度不代表相同集合。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第19題：行秩與列秩"}, "multiple": true}, {"id": "e019", "topic": "座標與相似", "en": "B=P⁻¹AP with P invertible. If Av=λv and v≠0, which vector is guaranteed to be a λ-eigenvector of B?", "zh": "B=P⁻¹AP，且Av=λv、v非零，B對應λ的特徵向量是哪個？", "options": ["P⁻¹v", "Pv", "v in every case（必定仍是v）", "0"], "answer": [0], "explanation": "計算B(P⁻¹v)=P⁻¹APP⁻¹v=P⁻¹Av=λP⁻¹v。P⁻¹可逆且v非零，所以新向量也非零。相似矩陣保留特徵值，特徵向量座標通常跟著改變。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第20題：相似矩陣"}, "multiple": true}, {"id": "e020", "topic": "特徵值與對角化", "en": "An equation Az=9z is satisfied by z=0. What can be concluded about 9?", "zh": "z=0滿足Az=9z，可以因此說9是特徵值嗎？", "options": ["No; a nonzero solution is required（不能，需非零解）", "Yes, for every square A（可以，任何方陣都適用）", "Yes, if A has real entries（實矩陣即可）"], "answer": [0], "explanation": "零向量對任何數λ都滿足A0=λ0，完全無法辨認特徵值。必須有v≠0滿足Av=λv；等價地，A−λI不可逆，即det(A−λI)=0。特徵值可為0，但特徵向量不能為0。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第4頁第20題：特徵向量非零條件"}, "multiple": true}, {"id": "e021", "topic": "特徵值與對角化", "en": "For x′=3x+2y and y′=2x+3y, find the eigenvalues of the coefficient matrix.", "zh": "聯立方程x′=3x+2y、y′=2x+3y的係數矩陣，特徵值為何？", "options": ["1 and 5", "2 and 3", "3 and 3", "−1 and −5"], "answer": [0], "explanation": "係數矩陣是[[3,2],[2,3]]。特徵方程(3−λ)²−4=0，故3−λ=±2，得到λ=1、5。一般矩陣不能直接讀對角元素當特徵值；三角矩陣才有這個保證。", "kind": "考古題考點改編", "level": 2, "source": {"title": "臺大 114 工程數學 C", "url": "https://exam.lib.ntu.edu.tw/sites/default/files/exam//graduate/114/114-290.pdf", "locator": "原卷第3頁第14題：聯立微分方程的特徵值"}, "multiple": true},{"id":"tcu001","topic":"秩與線性方程","en":"If A is a 4 × 7 matrix of rank 3, then nullity(A) equals 4.","zh":"A 是 4 × 7 矩陣且 rank=3，則 nullity(A)=4。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"nullity(A)=7−3=4。秩－零化度定理使用「欄數」7，不是列數4。","kind":"台聯重點加強・原創","level":2},{"id":"tcu002","topic":"秩與線性方程","en":"If A is an m × n matrix, rank(A) can exceed min(m,n).","zh":"對 m × n 矩陣，rank(A) 可以大於 min(m,n)。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"rank(A)≤min(m,n)，因為主元數不能超過任何一個方向的維度。","kind":"台聯重點加強・原創","level":2},{"id":"tcu003","topic":"秩與線性方程","en":"For any real matrix A, rank(AᵀA) = rank(A).","zh":"任意實矩陣 A 都有 rank(AᵀA)=rank(A)。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"N(AᵀA)=N(A)，由 xᵀAᵀAx=||Ax||²，因此兩者零化度相同，欄數相同，秩相同。","kind":"台聯重點加強・原創","level":2},{"id":"tcu004","topic":"秩與線性方程","en":"If rank(A)=rank([A|b]), then Ax=b is consistent.","zh":"若 rank(A)=rank([A|b])，則 Ax=b 有解。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"Rouché–Capelli 判準：增廣矩陣與係數矩陣的秩相同等價於有解。","kind":"台聯重點加強・原創","level":2},{"id":"tcu005","topic":"秩與線性方程","en":"If Ax=b is consistent and A has a nonzero nullspace, then Ax=b has infinitely many solutions over R.","zh":"若 Ax=b 有解且 N(A) 有非零向量，實數域中有無限多解。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"若 x₀ 是特解、v≠0 且 Av=0，則 x₀+tv 對所有實數 t 都是解。","kind":"台聯重點加強・原創","level":2},{"id":"tcu006","topic":"秩與線性方程","en":"An n × n matrix is invertible if and only if its nullity is zero.","zh":"n × n 方陣可逆若且唯若 nullity=0。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"方陣可逆 ⇔ N(A)={0} ⇔ rank(A)=n。","kind":"台聯重點加強・原創","level":2},{"id":"tcu007","topic":"秩與線性方程","en":"Elementary row operations always preserve the nullspace of A.","zh":"初等列運算（row operations）必定保留矩陣 A 的 nullspace。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"列運算對應左乘可逆矩陣 E；EAx=0 ⇔ Ax=0。注意一般不保留 column space 本身。","kind":"台聯重點加強・原創","level":2},{"id":"tcu008","topic":"秩與線性方程","en":"Elementary row operations always preserve the column space of A as a subset of R^m.","zh":"列運算（row operations）必定保留 A 的 column space 作為 R^m 的集合。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"EA 的 column space 是 E(Col(A))，維度不變但空間方向可能改變。","kind":"台聯重點加強・原創","level":2},{"id":"tcu009","topic":"秩與線性方程","en":"The row rank of a matrix may differ from its column rank.","zh":"同一矩陣的 row rank 與 column rank 可以不同。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"對任何域上的矩陣，row rank = column rank = rank(A)。","kind":"台聯重點加強・原創","level":2},{"id":"tcu010","topic":"線性轉換","en":"For T: R^5 → R^3 with rank(T)=2, nullity(T)=3.","zh":"T: R^5→R^3 且 rank(T)=2，則 nullity(T)=3。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"rank(T)+nullity(T)=dim(domain)=5，而不是 dim(codomain)=3。","kind":"台聯重點加強・原創","level":2},{"id":"tcu011","topic":"線性轉換","en":"The range R(T) is a subspace of the codomain.","zh":"R(T) 是陪域（codomain）的子空間。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"R(T)={T(v): v 在定義域}；對線性組合封閉，位於 codomain。","kind":"台聯重點加強・原創","level":2},{"id":"tcu012","topic":"線性轉換","en":"The kernel N(T) is a subspace of the codomain.","zh":"N(T) 是陪域（codomain）的子空間。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"kernel={v 在 domain:T(v)=0}，所以是定義域的子空間。","kind":"台聯重點加強・原創","level":2},{"id":"tcu013","topic":"線性轉換","en":"If T: R^3 → R^4 is injective, then rank(T)=3.","zh":"T: R^3→R^4 是單射，則 rank(T)=3。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"單射 ⇔ nullity=0；由 rank–nullity 得 rank=dim(domain)=3。","kind":"台聯重點加強・原創","level":2},{"id":"tcu014","topic":"線性轉換","en":"A linear map from R^4 onto R^3 can be injective.","zh":"從 R^4 映到 R^3 的線性滿射能同時是單射。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"滿射需要 rank=3，但 nullity=4−3=1，所以不可能單射。","kind":"台聯重點加強・原創","level":2},{"id":"tcu015","topic":"線性轉換","en":"For any linear T, T(0)=0.","zh":"任意線性轉換 T 皆有 T(0)=0。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"T(0)=T(0+0)=T(0)+T(0)，故 T(0)=0。","kind":"台聯重點加強・原創","level":2},{"id":"tcu016","topic":"基底與維度","en":"Any linearly independent set in an n-dimensional space has at most n vectors.","zh":"n 維向量空間中，線性獨立集合至多 n 個向量。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"超過維度的任意向量集合必定線性相依。","kind":"台聯重點加強・原創","level":2},{"id":"tcu017","topic":"基底與維度","en":"Every spanning set of R^n containing n vectors is a basis.","zh":"R^n 中恰有 n 個向量的生成集合一定是基底。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"在 n 維空間中，n 個向量若 spanning 就自動線性獨立。","kind":"台聯重點加強・原創","level":2},{"id":"tcu018","topic":"基底與維度","en":"The empty set is linearly independent.","zh":"空集合是線性獨立集合。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"線性獨立定義是「沒有非平凡線性關係」；空集合滿足此條件，是零維空間的基底。","kind":"台聯重點加強・原創","level":2},{"id":"tcu019","topic":"基底與維度","en":"A nonzero vector by itself is always a linearly independent set.","zh":"任何非零向量單獨構成線性獨立集合。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"cv=0 且 v≠0 時只能 c=0。","kind":"台聯重點加強・原創","level":2},{"id":"tcu020","topic":"特徵值與相似","en":"If A is invertible, zero is not an eigenvalue of A.","zh":"若 A 可逆，0 不是 A 的特徵值。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"0 是特徵值 ⇔ Ax=0 有非零解 ⇔ A 奇異。","kind":"台聯重點加強・原創","level":2},{"id":"tcu021","topic":"特徵值與相似","en":"Two matrices with the same eigenvalues are necessarily similar.","zh":"有相同特徵值的兩個矩陣一定相似。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"例如 2×2 的 I 與非平凡 Jordan block J₂(1)，特徵值同為1但不相似。","kind":"台聯重點加強・原創","level":2},{"id":"tcu022","topic":"特徵值與相似","en":"Every real symmetric matrix is orthogonally diagonalizable.","zh":"每個實對稱矩陣都能正交對角化。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"實譜定理：A=Aᵀ ⇔ 存在正交 Q 使 QᵀAQ 為對角矩陣。","kind":"台聯重點加強・原創","level":2},{"id":"tcu023","topic":"特徵值與相似","en":"An n × n matrix with n distinct eigenvalues is diagonalizable over the field containing those eigenvalues.","zh":"n 階矩陣若有 n 個互異特徵值，在包含這些特徵值的域上可對角化。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"不同特徵值的特徵向量線性獨立，得到 n 個特徵向量基底。","kind":"台聯重點加強・原創","level":2},{"id":"tcu024","topic":"特徵值與相似","en":"A repeated eigenvalue forces a matrix to be non-diagonalizable.","zh":"矩陣只要有重複特徵值，就一定無法對角化。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"單位矩陣的特徵值全部重複，卻已是對角矩陣。","kind":"台聯重點加強・原創","level":2},{"id":"tcu025","topic":"正交與投影","en":"For real A, the nullspace N(A) is the orthogonal complement of Row(A).","zh":"對實矩陣 A，N(A)=Row(A) 的正交補。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"Ax=0 ⇔ x 與 A 的每個 row 向量內積都為0。","kind":"台聯重點加強・原創","level":2},{"id":"tcu026","topic":"正交與投影","en":"If A has independent columns, then AᵀA is positive definite.","zh":"實矩陣 A 的欄向量線性獨立 ⇒ AᵀA 正定。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"對 x≠0，Ax≠0，因此 xᵀAᵀAx=||Ax||²>0。","kind":"台聯重點加強・原創","level":2},{"id":"tcu027","topic":"正交與投影","en":"An orthogonal real matrix Q satisfies Q⁻¹=Qᵀ.","zh":"實正交矩陣 Q 滿足 Q⁻¹=Qᵀ。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"QᵀQ=I 就是正交矩陣定義。","kind":"台聯重點加強・原創","level":2},{"id":"tcu028","topic":"正交與投影","en":"The least-squares solution to Ax=b always satisfies Ax=b exactly.","zh":"Ax=b 的最小平方解必然使 Ax=b 完全成立。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"最小平方是最小化 ||Ax−b||²；當 b 不在 Col(A) 時，殘差不為零。","kind":"台聯重點加強・原創","level":2},{"id":"tcu029","topic":"正定與矩陣性質","en":"A real symmetric positive definite matrix has strictly positive eigenvalues.","zh":"實對稱正定矩陣的全部特徵值都大於0。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"取單位特徵向量 v，vᵀAv=λ||v||²>0 ⇒ λ>0。","kind":"台聯重點加強・原創","level":2},{"id":"tcu030","topic":"正定與矩陣性質","en":"For real A, AᵀA is always positive definite.","zh":"對任意實矩陣 A，AᵀA 一定正定。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"AᵀA 永遠半正定，只有 A 的 columns 線性獨立時才正定。","kind":"台聯重點加強・原創","level":2},{"id":"tcu031","topic":"正定與矩陣性質","en":"If det(A)=0 for a 2 × 2 matrix, then rank(A)=1.","zh":"2×2 矩陣 det(A)=0 ⇒ rank(A)=1。","options":["True（正確）","False（錯誤）"],"answer":[1],"explanation":"零矩陣 det=0 但 rank=0；只能推得 rank≤1。","kind":"台聯重點加強・原創","level":2},{"id":"tcu032","topic":"正定與矩陣性質","en":"For square matrices of the same size, det(AB)=det(A)det(B).","zh":"同階方陣滿足 det(AB)=det(A)det(B)。","options":["True（正確）","False（錯誤）"],"answer":[0],"explanation":"行列式乘法定理；不要求 A、B 可逆。","kind":"台聯重點加強・原創","level":2}];
const WORDS=[["rank", "秩", "rank(A)=dim Col(A)=dim Row(A)，等於 pivot 數；不是非零元素數。"], ["nullity", "零度", "nullity(A)=dim N(A)，等於自由變數數；A 有 n 個 column 時為 n−rank(A)。"], ["kernel", "核空間", "ker(T)=N(T)={v∈V:T(v)=0}。收集被映成零的輸入。"], ["range", "像空間", "R(T)=Im(T)={T(v):v∈V}。所有實際能得到的輸出，可能只是陪域的一部分。"], ["domain", "定義域", "T:V→W 的 V，是允許輸入的空間。"], ["codomain", "陪域", "T:V→W 的 W，是預先指定的輸出所在空間，不一定等於 range。"], ["column space", "直行空間", "Col(A) 由 A 的直向 column 所張成；m×n 矩陣的 Col(A)⊆ℝᵐ。 對線性映射 x↦Ax，它也就是像空間 R(A)。"], ["row space", "橫列空間", "Row(A) 由 A 的橫向 row 所張成；m×n 矩陣的 Row(A)⊆ℝⁿ。"], ["null space", "零空間", "N(A)={x:Ax=0}⊆ℝⁿ；不是等於數字 0。 它也稱為核空間 kernel。"], ["left null space", "左零空間", "對實 m×n 矩陣 A，左零空間為 N(Aᵀ)⊆ℝᵐ，與 Col(A) 正交。複數內積情況改用共軛轉置 A*。"], ["span", "張成空間", "span{v₁,…,vₖ} 是所有線性組合 c₁v₁+⋯+cₖvₖ；係數各自任意。"], ["linear combination", "線性組合", "c₁v₁+⋯+cₖvₖ，係數來自指定純量域。"], ["linearly independent", "線性獨立", "c₁v₁+⋯+cₖvₖ=0 只允許所有 cᵢ=0。"], ["linearly dependent", "線性相依", "存在不全為零的係數，使線性組合等於零。"], ["basis", "基底", "同時線性獨立且張成整個空間的一組向量。"], ["dimension", "維度", "有限維空間任一基底的向量個數；維度是數字，基底是向量集合。"], ["subspace", "子空間", "包含零向量且對加法與純量乘法封閉的子集合。"], ["intersection", "交集", "U∩W 同時屬於 U 與 W 的向量；兩子空間交集仍是子空間。"], ["sum of subspaces", "子空間之和", "U+W={u+w:u∈U,w∈W}；通常不是 U∪W。"], ["direct sum", "直和", "U⊕W 表示 U+W 且 U∩W={0}，每個向量分解唯一。"], ["linear transformation", "線性轉換", "T(au+bv)=aT(u)+bT(v)，必有 T(0)=0，但只滿足 T(0)=0 還不夠。"], ["one-to-one", "單射", "不同輸入必有不同輸出；線性映射等價於 ker(T)={0}。"], ["onto", "滿射", "每個陪域向量都有原像，即 R(T)=W。"], ["bijective", "雙射", "同時單射與滿射。"], ["isomorphism", "同構", "可逆的線性映射；有限維同一純量域的空間同構當且僅當維度相同。"], ["consistent", "有解／相容", "方程組至少有一個解，不代表解唯一。"], ["inconsistent", "無解／不相容", "方程組不存在任何解。"], ["homogeneous system", "齊次方程組", "Ax=0，必有零解；是否有非零解取決於 nullity。"], ["trivial solution", "零解", "齊次方程的 x=0。"], ["nontrivial solution", "非零解", "齊次方程中 x≠0 的解；不是指每個分量都非零。"], ["augmented matrix", "增廣矩陣", "增廣矩陣 [A|b] 是把右端向量 b 接在係數矩陣 A 的右邊。Ax=b 有解的充要條件為 rank(A)=rank([A|b])。"], ["pivot", "主元", "階梯形矩陣每個非零 row 的領頭非零位置；pivot 數等於 rank。"], ["free variable", "自由變數", "非 pivot column 對應的未知數，數目為 n−rank(A)。"], ["row equivalent", "列等價（橫向運算）", "可用初等 row operations 互相轉換；保留 row space 與 null space，不一定保留 column space。"], ["reduced row echelon form", "最簡列階梯形", "RREF 的 pivot 為 1 且所在 column 其他元素為 0；每個矩陣的 RREF 唯一。"], ["invertible", "可逆", "方陣存在雙邊反矩陣 A⁻¹；等價於滿秩、det(A)≠0。"], ["singular", "奇異", "不可逆的方陣；det(A)=0。"], ["nonsingular", "非奇異", "可逆方陣；不要和非零矩陣混淆。"], ["transpose", "轉置", "Aᵀ 交換 row 與 column；(AB)ᵀ=BᵀAᵀ。"], ["conjugate transpose", "共軛轉置", "A* 先取複共軛再轉置；複數內積需要共軛。"], ["trace", "跡", "方陣對角元素之和；也等於含代數重數的特徵值總和。"], ["determinant", "行列式", "方陣的純量；det(AB)=det(A)det(B)，一般不能對加法拆開。"], ["cofactor", "餘因子", "Cᵢⱼ=(−1)ⁱ⁺ʲ 乘上刪除第 i row、第 j column 後的行列式。"], ["adjugate", "古典伴隨矩陣", "adj(A) 是 cofactor matrix 的轉置；A adj(A)=det(A)I。"], ["eigenvalue", "特徵值", "存在非零 v 使 Av=λv 的 λ；λ 可以是 0。"], ["eigenvector", "特徵向量", "滿足 Av=λv 的非零向量；零向量不是特徵向量。"], ["eigenspace", "特徵空間", "Eλ=N(A−λI)，包含零向量。"], ["algebraic multiplicity", "代數重數", "λ 作為特徵多項式根的重數。"], ["geometric multiplicity", "幾何重數", "dim N(A−λI)，即該特徵空間的維度。"], ["diagonalizable", "可對角化", "存在可逆 P 使 P⁻¹AP 為對角矩陣，等價於有 n 個獨立特徵向量。"], ["similar", "相似", "B=P⁻¹AP。代表同一線性算子在不同基底下的矩陣。"], ["characteristic polynomial", "特徵多項式", "此處採 det(tI−A)，根即特徵值。"], ["minimal polynomial", "最小多項式", "使 m(A)=0 的最低次首一多項式；整除特徵多項式。"], ["orthogonal", "正交", "向量內積為 0；非零正交向量必線性獨立。"], ["orthonormal", "標準正交", "互相正交且每個向量長度都為 1。"], ["orthogonal matrix", "正交矩陣", "實方陣 QᵀQ=I，因此 Q⁻¹=Qᵀ；保長度與內積。"], ["orthogonal complement", "正交補空間", "W⊥ 為與 W 中每個向量都正交的所有向量。"], ["projection", "投影", "一般投影算子 P 滿足 P²=P；正交投影另要求 Pᵀ=P（實數標準內積）。"], ["least squares", "最小平方法", "最小化 ‖Ax−b‖²；實數情況滿足 normal equations AᵀAx=Aᵀb，複數情況改用共軛轉置 A*。"], ["normal equations", "正規方程式", "實數情況為 AᵀAx=Aᵀb；A 滿 column rank 時解唯一。複數情況將 Aᵀ 改為 A*。"], ["symmetric", "對稱", "實矩陣 Aᵀ=A，可正交對角化。"], ["Hermitian", "厄米矩陣", "複矩陣 A*=A，特徵值皆為實數。"], ["positive definite", "正定", "此處指實對稱 A，對所有非零 x，xᵀAx>0。"], ["positive semidefinite", "半正定", "此處指實對稱 A，對所有 x，xᵀAx≥0；可以有零特徵值。"], ["idempotent", "冪等", "A²=A；特徵值只能是 0 或 1。"], ["nilpotent", "冪零", "存在正整數 k 使 Aᵏ=0；不表示 A 本身一定為 0。"], ["unitary", "酉矩陣", "複方陣 U*U=I，是正交矩陣的複數對應。"], ["singular value", "奇異值", "A*A 特徵值的非負平方根；與 A 的特徵值不同。"], ["necessary condition", "必要條件", "P 是 Q 的必要條件表示 Q⇒P；有 P 不保證 Q。"], ["sufficient condition", "充分條件", "P 是 Q 的充分條件表示 P⇒Q。"], ["if and only if", "若且唯若／充要", "P iff Q 表示兩個方向 P⇒Q 與 Q⇒P 都成立。"], ["at most", "至多", "at most k 表示 ≤k，不是 ≥k。"], ["at least", "至少", "at least k 表示 ≥k，不是 ≤k。"], ["distinct", "互異", "distinct eigenvalues 表示不同數值的特徵值，不是計入重數後的個數。"], ["nonzero", "非零", "非零向量只要求至少一個分量不為零。"], ["for every", "對每一個", "全稱量詞；要推翻只需找到一個反例。"], ["there exists", "存在至少一個", "存在量詞；要證明只需構造一個符合條件的例子。"], ["unique", "唯一", "恰有一個，包含存在性與不超過一個這兩件事。"]];
const FORMULAS=[["先分清楚輸入與輸出", "T: V → W\nN(T) ⊆ V；R(T) ⊆ W", "N(T) 收集「被送成零的輸入」；R(T) 收集「實際得到的輸出」。N(T) 是集合，nullity(T) 才是數字。"], ["秩－零度定理", "rank(T) + nullity(T) = dim V", "前提：V 有限維。右邊是定義域維度，不是陪域維度。對 A∈ℝᵐˣⁿ，rank(A)+dim N(A)=n。"], ["四個基本子空間", "dim Col(A) = dim Row(A) = r\ndim N(A) = n−r\ndim N(Aᵀ) = m−r", "Col(A)、N(Aᵀ) 在 ℝᵐ；Row(A)、N(A) 在 ℝⁿ。row 橫向、column 直向。"], ["單射、滿射、雙射", "單射 ⇔ N(T)={0}\n滿射 ⇔ R(T)=W\n雙射 ⇔ 單射且滿射", "有限維且 dim V=dim W 時，單射、滿射、可逆三者等價。維度不同不能直接套。"], ["方程組有沒有解", "Ax=b 有解 ⇔ b∈Col(A)\n⇔ rank(A)=rank([A|b])", "有解後，若 rank(A)=n 則唯一解；rank(A)<n 則在實數域有無限多解。Ax=0 永遠有零解。"], ["所有解的結構", "x = xₚ + z，z∈N(A)", "xₚ 是 Ax=b 的一個特解。b≠0 時整個解集通常是仿射集合，不是子空間。"], ["乘積與和的秩", "rank(AB) ≤ min(rank A, rank B)\nrank(A+B) ≤ rank A + rank B", "A 為 m×n、B 為 n×p 時，rank(AB)≥rank A+rank B−n。加法式需要相同尺寸。"], ["AB=0 的空間意思", "AB=0 ⇔ Col(B)⊆N(A)", "B 先作用，所有 B 能產生的輸出都被 A 送成零。不是 Col(A)⊆N(B)。"], ["和空間與直和", "dim(U+W)=dim U+dim W−dim(U∩W)\nU⊕W ⇔ U∩W={0}", "U、W 為同一有限維空間的子空間。直和使分解唯一；聯集通常不是子空間。"], ["可逆矩陣的等價條件", "rank A=n ⇔ det A≠0 ⇔ N(A)={0}\n⇔ 0 不是 A 的特徵值", "此處 A 必須是 n×n 方陣。非零矩陣不代表可逆；非方陣要區分左逆與右逆。"], ["逆矩陣與轉置", "(AB)⁻¹=B⁻¹A⁻¹\n(AB)ᵀ=BᵀAᵀ\n(Aᵀ)⁻¹=(A⁻¹)ᵀ", "逆矩陣公式前提是各因子皆為同階可逆方陣。注意乘積次序反過來。"], ["行列式基本運算", "det(AB)=det A · det B\ndet(cA)=cⁿ det A\ndet(Aᵀ)=det A", "A、B 為 n 階方陣。交換兩個 row 變號；一個 row 乘 c，det 乘 c；加上另一 row 的倍數不變。"], ["伴隨矩陣", "A adj(A)=adj(A)A=det(A)I\nA⁻¹=adj(A)/det(A)", "第一式奇異矩陣也成立；第二式只有 det A≠0 時可用。adj(A) 是餘因子矩陣的轉置。"], ["特徵值與跡", "Av=λv，v≠0\ntr A=Σλᵢ；det A=Πλᵢ", "特徵值需按代數重數計算，在複數域可將所有根算齊。零向量不是特徵向量。"], ["特徵值的函數", "Av=λv ⇒ p(A)v=p(λ)v\nA 可逆時：A⁻¹v=(1/λ)v", "p 為多項式。不要把矩陣加法的特徵值逐項相加；一般 A、B 沒有共同特徵向量。"], ["何時可對角化", "A=PDP⁻¹\n⇔ A 有 n 個線性獨立特徵向量", "每個特徵值的幾何重數需等於代數重數，且特徵多項式在指定域可完全分解。n 個互異特徵值是充分條件，不是必要條件。"], ["重數別混了", "1 ≤ 幾何重數 ≤ 代數重數\n幾何重數 = dim N(A−λI)", "適用 λ 為特徵值。重根仍可能可對角化，例如 I；也可能不可，如非平凡 Jordan block。"], ["相似矩陣", "B=P⁻¹AP", "相同特徵多項式、rank、trace、det、最小多項式；反過來，只有相同特徵值不保證相似。"], ["正交補空間", "N(A)=Row(A)⊥\nN(Aᵀ)=Col(A)⊥\ndim W + dim W⊥ = n", "這裡採 ℝⁿ 標準內積。複數矩陣對應使用共軛轉置 A*。"], ["投影公式", "projᵤ b = u(uᵀb)/(uᵀu)\nP=A(AᵀA)⁻¹Aᵀ", "第一式 u≠0。第二式 A 必須有線性獨立的 columns；若 Q columns 標準正交，P=QQᵀ。"], ["最小平方", "AᵀAx̂=Aᵀb\nb−Ax̂ ⟂ Col(A)", "最小平方解一定存在；當 A 滿 column rank 時唯一。AᵀA 奇異時不能直接取逆。"], ["正定與半正定", "A=Aᵀ\n正定 ⇔ 所有 λᵢ>0\n半正定 ⇔ 所有 λᵢ≥0", "本頁採實對稱矩陣定義。正定可用所有領先主子式>0 判定；半正定不能只檢查領先主子式≥0。"], ["Gram 矩陣", "xᵀAᵀAx=‖Ax‖² ≥ 0\nN(AᵀA)=N(A)", "實數域：AᵀA 永遠半正定；A 滿 column rank 才正定。rank(AᵀA)=rank(A)。"], ["SVD", "A=UΣVᵀ\nσᵢ=√λᵢ(AᵀA)", "任意實矩陣皆存在 SVD；非零奇異值數目等於 rank。σᵢ 非負，不是直接取 A 的特徵值。"], ["Cayley–Hamilton 與最小多項式", "χA(A)=0\nmA(t) 整除 χA(t)", "可對角化等價於最小多項式在指定域分裂成互異一次因子。χA 的重根本身不排除可對角化。"], ["座標換基底", "[v]C = P(C←B)[v]B\n[T]C = P(C←B)[T]B P(C←B)⁻¹", "P 的第 j 個 column 是 [bⱼ]C。第二式用在同一空間上的線性算子；先看清矩陣把哪個座標送到哪個座標。"]];
